window.BUNDLED_QUESTION_BANKS = [{"name":"OOPs — Core MCQs","icon":"⌘","description":"Core OOP concepts and placement MCQs","questions":[{"q":"Which statement best describes object-oriented programming?","opts":["A. A style based only on global variables","B. A style that organizes programs around objects containing state and behavior","C. A method of writing only database queries","D. A programming style that prohibits functions"],"ans":"B","explanation":"OOP models a program using objects that combine data (state) and operations (behavior)."},{"q":"Which OOP concept is most directly represented by a blueprint used to create multiple objects?","opts":["A. Constructor","B. Class","C. Destructor","D. Namespace"],"ans":"B","explanation":"A class defines the common structure and behavior that its objects can have."},{"q":"An individual object created from a class is called:","opts":["A. An instance","B. An operator","C. A package","D. A header"],"ans":"A","explanation":"An object is an instance of a class."},{"q":"Which pair most accurately describes an object's basic contents?","opts":["A. State and behavior","B. Compiler and linker","C. Header and library","D. Loop and condition"],"ans":"A","explanation":"State is represented by data members; behavior is represented by methods."},{"q":"In C++, which keyword begins a class declaration?","opts":["A. object","B. structclass","C. class","D. define"],"ans":"C","explanation":"The class keyword introduces a class declaration."},{"q":"What is the default access level for members of a C++ class?","opts":["A. public","B. protected","C. private","D. package"],"ans":"C","explanation":"Class members are private by default in C++."},{"q":"What is the default access level for members of a C++ struct?","opts":["A. private","B. public","C. protected","D. friend"],"ans":"B","explanation":"Struct members are public by default in C++, unlike class members."},{"q":"Which access specifier allows access from code that can access the object, subject to normal access rules?","opts":["A. private","B. protected","C. public","D. friend-only"],"ans":"C","explanation":"Public members are accessible wherever the object itself is accessible, subject to other language rules."},{"q":"Which member function is automatically called when an object is initialized with a matching construction operation?","opts":["A. Destructor","B. Constructor","C. Mutator only","D. Friend function"],"ans":"B","explanation":"A constructor initializes an object when it is created."},{"q":"Which special member function is normally called when an object's lifetime ends?","opts":["A. Constructor","B. Destructor","C. Getter","D. Overloaded operator"],"ans":"B","explanation":"A destructor performs cleanup when an object's lifetime ends."},{"q":"Which statement about a constructor in C++ is correct?","opts":["A. It must return int","B. It has the same name as the class","C. It must be static","D. It is inherited exactly like an ordinary member function"],"ans":"B","explanation":"A constructor has the class name and no return type."},{"q":"What is the main purpose of a getter method?","opts":["A. To destroy an object","B. To provide controlled access to a value","C. To create a derived class","D. To overload every operator"],"ans":"B","explanation":"A getter exposes information while allowing the class to control how it is accessed."},{"q":"What is the main purpose of a setter method?","opts":["A. To update a value through a controlled interface","B. To allocate the class definition","C. To force multiple inheritance","D. To call a destructor manually in every case"],"ans":"A","explanation":"A setter can validate or restrict updates to an object's state."},{"q":"Which concept bundles data and the methods that operate on it into one unit?","opts":["A. Encapsulation","B. Recursion","C. Compilation","D. Tokenization"],"ans":"A","explanation":"Encapsulation groups data and related behavior and controls access to internal state."},{"q":"Which OOP pillar means exposing essential operations while hiding implementation details?","opts":["A. Inheritance","B. Abstraction","C. Overloading","D. Instantiation"],"ans":"B","explanation":"Abstraction presents a useful interface while concealing unnecessary implementation detail."},{"q":"Which OOP pillar allows a new class to reuse and extend an existing class?","opts":["A. Inheritance","B. Encapsulation","C. Compilation","D. Casting"],"ans":"A","explanation":"Inheritance creates a derived class based on an existing base class."},{"q":"Which concept lets the same interface produce different behavior for different object types?","opts":["A. Polymorphism","B. Data hiding only","C. Constructor chaining only","D. Namespacing"],"ans":"A","explanation":"Polymorphism allows a common interface to represent different implementations."},{"q":"Which is an example of compile-time polymorphism in C++?","opts":["A. Virtual function overriding through a base pointer","B. Function overloading","C. Dynamic dispatch only","D. Runtime type identification"],"ans":"B","explanation":"Overloaded functions are selected by the compiler based on the call's arguments."},{"q":"Which is typically an example of runtime polymorphism in C++?","opts":["A. Function overloading","B. Constructor overloading","C. Virtual function overriding","D. Default arguments"],"ans":"C","explanation":"Virtual functions support dynamic dispatch based on the actual object type."},{"q":"What does the `this` pointer refer to in a non-static C++ member function?","opts":["A. The base class object only","B. The current object","C. The next object allocated","D. The class definition itself"],"ans":"B","explanation":"`this` points to the object on which the non-static member function is invoked."},{"q":"What is printed by `class A { public: A(){ cout << \"A\"; } }; int main(){ A x; A y; }`?","opts":["A. A","B. AA","C. No output","D. Compilation error"],"ans":"B","explanation":"Each of the two objects is constructed, so the constructor prints A twice."},{"q":"Given `class Box { public: int n; Box(int x): n(x) {} }; Box b(7);`, what is `b.n`?","opts":["A. 0","B. 1","C. 7","D. Undefined because constructors cannot take parameters"],"ans":"C","explanation":"The member initializer list initializes n with the argument x, which is 7."},{"q":"Which statement about a user-declared constructor is true?","opts":["A. It can have a return type","B. Its name must differ from the class name","C. It has no return type","D. It must always be private"],"ans":"C","explanation":"Constructors do not declare a return type, not even void."},{"q":"What happens with `class A { public: A(int) {} }; int main(){ A a; }`?","opts":["A. It calls A(int) with zero","B. It compiles and initializes a to zero","C. It fails because no zero-argument constructor is available","D. It calls the destructor instead"],"ans":"C","explanation":"Declaring a parameterized constructor means the compiler does not automatically provide a default constructor."},{"q":"What is the output? `class A { public: A(){cout<<\"C\";} ~A(){cout<<\"D\";} }; int main(){ A a; }`","opts":["A. CD","B. DC","C. C only","D. D only"],"ans":"A","explanation":"Construction occurs first and destruction occurs when the local object leaves scope."},{"q":"When an object is passed by value to a function, what generally happens?","opts":["A. The original object is always moved","B. A separate parameter object is initialized, commonly using a copy or move constructor","C. No parameter object exists","D. The class destructor is disabled"],"ans":"B","explanation":"Pass-by-value initializes a distinct parameter object; copy elision or move semantics may affect the exact operations."},{"q":"What is the likely issue with `class A { int x; public: A(int n){ x=n; } }; A a(5); A b=a;`?","opts":["A. Copying is forbidden for all classes","B. The compiler can generate a copy constructor that copies x","C. The copy always resets x to zero","D. A destructor is required before copying"],"ans":"B","explanation":"For this simple class, the implicitly generated copy constructor copies the member value."},{"q":"For a class that owns a raw dynamically allocated resource, why might a custom copy constructor be needed?","opts":["A. To make every method virtual","B. To avoid unintended shallow copying and manage independent ownership correctly","C. To make the class abstract","D. To change private members to public"],"ans":"B","explanation":"A shallow copy of an owned raw pointer can lead to shared ownership bugs or double deletion."},{"q":"Which order is correct when a derived object is constructed?","opts":["A. Derived members, base class, then derived body","B. Base class, derived members, then derived constructor body","C. Derived body, base class, then members","D. Destruction order"],"ans":"B","explanation":"The base subobject is initialized first, then members in declaration order, then the constructor body."},{"q":"In what order are local automatic objects destroyed when several are created in the same scope?","opts":["A. First created, first destroyed","B. Random order","C. Last created, first destroyed","D. All at program start"],"ans":"C","explanation":"Objects with automatic storage duration are destroyed in reverse order of completed construction."},{"q":"A class stores `balance` as private and provides `deposit()` that rejects negative amounts. What is the strongest reason for this design?","opts":["A. It makes the program procedural","B. It protects class invariants by controlling state changes","C. It guarantees no runtime errors","D. It prevents the object from being copied"],"ans":"B","explanation":"Private state and validated operations prevent callers from bypassing important rules."},{"q":"A method needs to be used by outside code but should not expose the object's internal representation. Which design is best?","opts":["A. Make every field public","B. Provide a public operation and keep implementation data private","C. Put all fields in global variables","D. Use only protected members"],"ans":"B","explanation":"A stable public interface can hide private implementation details."},{"q":"Which statement about `protected` members in C++ is most accurate?","opts":["A. They are accessible from every unrelated function","B. They are accessible to the class and eligible derived-class contexts, subject to C++ access rules","C. They are always public","D. They can only be accessed by constructors"],"ans":"B","explanation":"Protected access is primarily for the class and derived classes, with specific language restrictions."},{"q":"A friend function can access a class's private members. Which statement is correct?","opts":["A. Friendship is automatically mutual","B. Friendship is inherited by every derived class","C. Friendship grants specified access but does not make the function a member","D. Every global function is a friend"],"ans":"C","explanation":"A friend is granted access explicitly but remains a non-member function unless separately declared as a member."},{"q":"Why is exposing a public data member often less flexible than providing a public method?","opts":["A. Public data cannot store integers","B. A method can validate values and preserve invariants","C. Public data always uses more memory","D. Methods cannot be changed"],"ans":"B","explanation":"A method provides a control point for validation and future implementation changes."},{"q":"If `class Dog : public Animal`, which statement is usually true about public inheritance?","opts":["A. Dog is not related to Animal","B. A Dog can be treated as an Animal through the public base interface","C. Animal's private members become directly accessible in Dog","D. Dog cannot add new members"],"ans":"B","explanation":"Public inheritance models an is-a relationship, but private base members remain inaccessible directly to the derived class."},{"q":"What is the difference between public and private inheritance in C++?","opts":["A. They are identical","B. Public inheritance preserves public/protected access levels in the derived interface; private inheritance changes inherited public/protected members to private","C. Private inheritance prevents construction","D. Public inheritance makes private base members public"],"ans":"B","explanation":"The inheritance access specifier affects the accessibility of inherited public and protected members."},{"q":"Which inheritance structure has one derived class inheriting from two base classes?","opts":["A. Single inheritance","B. Multilevel inheritance","C. Multiple inheritance","D. Hierarchical inheritance"],"ans":"C","explanation":"Multiple inheritance means one class has more than one direct base class."},{"q":"Class C inherits from B, and B inherits from A. What is this structure called?","opts":["A. Multiple inheritance","B. Multilevel inheritance","C. Hybrid inheritance only","D. Encapsulation"],"ans":"B","explanation":"A chain of inheritance across levels is multilevel inheritance."},{"q":"Which statement about private members of a base class is correct?","opts":["A. They are directly accessible by derived-class methods","B. They are inherited as public members","C. They are part of the base subobject but cannot be accessed directly by derived-class code","D. They do not exist in a derived object"],"ans":"C","explanation":"The base subobject exists, but private access is restricted to the base class and its friends."},{"q":"What does the `protected` inheritance specifier do to inherited public and protected members?","opts":["A. Makes them public","B. Makes them protected in the derived class","C. Makes them private","D. Deletes them"],"ans":"B","explanation":"Under protected inheritance, inherited public and protected members become protected in the derived class."},{"q":"What is the diamond problem in multiple inheritance?","opts":["A. A class has too many methods","B. Two intermediate classes inherit from the same base and a final class inherits from both, potentially duplicating the base subobject","C. A constructor has four arguments","D. A class contains a private integer"],"ans":"B","explanation":"The diamond shape can create duplicate base subobjects and ambiguous member access."},{"q":"In C++, what is the usual purpose of virtual inheritance in a diamond hierarchy?","opts":["A. To prevent all polymorphism","B. To share a single virtual base subobject among the relevant derived paths","C. To make every member public","D. To prohibit constructors"],"ans":"B","explanation":"Virtual inheritance allows the most-derived object to contain one shared instance of the virtual base."},{"q":"If a derived class declares a member function with the same name as a base-class function but a different parameter list, what can happen?","opts":["A. The derived name can hide base overloads during lookup","B. The base function is always virtual","C. The program must be procedural","D. All base members become private"],"ans":"A","explanation":"Name hiding can occur; a `using Base::functionName;` declaration can bring base overloads into the derived scope."},{"q":"Which design most closely follows the Liskov Substitution Principle?","opts":["A. A subtype strengthens preconditions arbitrarily","B. A subtype can replace its base type without breaking expected client behavior","C. A subtype must expose all data publicly","D. A subtype must have fewer methods"],"ans":"B","explanation":"LSP requires derived types to preserve the behavioral expectations of the base abstraction."},{"q":"What is function overloading?","opts":["A. Same function name with different parameter lists in the same scope","B. Same function name and identical parameter list in unrelated files only","C. Redefining a variable","D. Calling a virtual function through a pointer"],"ans":"A","explanation":"Overloading is resolved using the function name and parameter types/counts."},{"q":"Can C++ overload functions solely by changing their return type?","opts":["A. Yes, always","B. Yes, if return types are different primitive types","C. No, return type alone is not enough to distinguish overloads","D. Only for constructors"],"ans":"C","explanation":"The overload set cannot be distinguished solely by return type."},{"q":"What is function overriding?","opts":["A. Defining a derived-class function that overrides a virtual base-class function with a compatible signature","B. Defining two unrelated functions with different names","C. Defining a constructor with arguments","D. Hiding all data members"],"ans":"A","explanation":"Overriding replaces a virtual function's implementation for a derived type."},{"q":"What is printed? `struct B{virtual void f(){cout<<\"B\";}}; struct D:B{void f() override{cout<<\"D\";}}; int main(){D d; B* p=&d; p->f();}`","opts":["A. B","B. D","C. BD","D. Compilation error"],"ans":"B","explanation":"Because f is virtual, the call dispatches to D::f based on the dynamic type of the object."},{"q":"If a base-class function is not virtual, what happens in `Base* p = &derived; p->show();` when both classes define `show()`?","opts":["A. The derived version is always called","B. The call is resolved using the static type Base*","C. Both versions run automatically","D. The code always fails to compile"],"ans":"B","explanation":"Without virtual dispatch, a call through a base pointer selects the base-class member function."},{"q":"What does the `override` keyword help the compiler verify?","opts":["A. That a function is a constructor","B. That a member function actually overrides a virtual base-class function","C. That a class has no private members","D. That a function is inline"],"ans":"B","explanation":"`override` makes a signature mismatch that prevents overriding a compile-time error."},{"q":"What is an abstract class in C++?","opts":["A. A class that has no data members","B. A class that cannot be instantiated directly because it has at least one pure virtual function","C. A class with only static functions","D. Any class with a private constructor"],"ans":"B","explanation":"A class with a pure virtual function is abstract until all such functions are implemented in a concrete derived class."},{"q":"Which declaration makes `draw()` a pure virtual function?","opts":["A. `void draw();`","B. `virtual void draw() = 0;`","C. `static void draw() = 0;`","D. `void virtual() draw;`"],"ans":"B","explanation":"The `= 0` syntax declares a pure virtual function."},{"q":"Why should a polymorphic base class usually have a virtual destructor when objects may be deleted through base pointers?","opts":["A. To make constructors virtual","B. To ensure the derived destructor is invoked when deleting a derived object through a base pointer","C. To avoid all allocations","D. To allow function overloading"],"ans":"B","explanation":"A virtual base destructor enables correct destruction through a base pointer."},{"q":"What is the output? `struct B{virtual void f(){cout<<1;}}; struct D:B{void f() override{cout<<2;}}; D d; B& r=d; r.f();`","opts":["A. 1","B. 2","C. 12","D. Compilation error"],"ans":"B","explanation":"A base reference bound to a derived object invokes the derived override because f is virtual."},{"q":"Which statement about constructors and virtual functions is correct?","opts":["A. Constructors can be virtual","B. Destructors can never be virtual","C. Constructors cannot be virtual, but destructors can be virtual","D. Both must be virtual in every class"],"ans":"C","explanation":"C++ constructors are not virtual; destructors may and often should be virtual in polymorphic base classes."},{"q":"What does object slicing mean?","opts":["A. Deleting half of an object","B. Copying a derived object into a base object by value, losing the derived-specific portion","C. Splitting a class into namespaces","D. Overloading a subscript operator"],"ans":"B","explanation":"Pass-by-value or assignment to a base object can slice off the derived portion."},{"q":"Which option best enables runtime polymorphism without slicing when working with derived objects?","opts":["A. Store each object as a base object by value","B. Use base-class references or pointers with virtual functions","C. Convert every method to static","D. Make all members public"],"ans":"B","explanation":"References and pointers preserve the dynamic object type, allowing virtual dispatch."},{"q":"A payment system supports CardPayment and UpiPayment through a common `pay()` interface. Which concept is most directly demonstrated when each implementation behaves differently?","opts":["A. Runtime polymorphism","B. Object slicing","C. Private inheritance only","D. Constructor delegation"],"ans":"A","explanation":"A common interface can dispatch to the implementation appropriate to the concrete payment type."},{"q":"Which example best demonstrates abstraction?","opts":["A. A caller must know every internal calculation to call `withdraw()`","B. A caller uses `withdraw(amount)` without needing to know the internal validation and ledger steps","C. All fields are public","D. The program has no methods"],"ans":"B","explanation":"Abstraction provides a simple interface and hides implementation details."},{"q":"Which statement best distinguishes encapsulation from abstraction?","opts":["A. They mean exactly the same thing in every context","B. Encapsulation groups and protects state/behavior; abstraction exposes essential features while hiding complexity","C. Abstraction means inheritance, encapsulation means polymorphism","D. Encapsulation only applies to databases"],"ans":"B","explanation":"They are related but emphasize different goals: controlled bundling/access versus simplified interfaces."},{"q":"A `Car` contains an `Engine` object as a required part of its design and manages its lifetime. Which relationship is most appropriate?","opts":["A. Composition","B. Generalization only","C. Function overloading","D. Friendship"],"ans":"A","explanation":"Composition models strong whole-part ownership, where the part's lifetime is tied to the whole in the design."},{"q":"A `Department` refers to `Professor` objects that can exist independently of the department. Which relationship is most likely?","opts":["A. Composition in every case","B. Aggregation","C. Inheritance","D. Overriding"],"ans":"B","explanation":"Aggregation models a whole-part or has-a relationship where the part can exist independently."},{"q":"A method receives a `Logger&` and uses it temporarily without owning or storing it. Which relationship is best described?","opts":["A. Dependency","B. Multiple inheritance","C. Composition","D. Diamond inheritance"],"ans":"A","explanation":"Dependency means one component temporarily uses another."},{"q":"Which is an example of an is-a relationship?","opts":["A. A Car has an Engine","B. A Dog is an Animal","C. An Order uses a PaymentService","D. A Team contains Players"],"ans":"B","explanation":"Public inheritance is often used to model a valid is-a relationship."},{"q":"Which is an example of a has-a relationship?","opts":["A. A Sparrow is a Bird","B. A Square is a Shape","C. A Computer has a CPU","D. A Manager is an Employee"],"ans":"C","explanation":"A computer containing or using a CPU is a has-a relationship."},{"q":"What is the purpose of operator overloading in C++?","opts":["A. To change an operator's meaning for user-defined types within language rules","B. To create new punctuation tokens","C. To change operator precedence for all code","D. To make private members public"],"ans":"A","explanation":"Operator overloading lets class types define suitable behavior for supported operators."},{"q":"Which operator cannot be overloaded in C++?","opts":["A. `+`","B. `[]`","C. `::`","D. `==`"],"ans":"C","explanation":"The scope-resolution operator `::` is among the operators that cannot be overloaded."},{"q":"Which statement about overloaded functions is correct?","opts":["A. They must differ by return type only","B. The compiler chooses an overload based on the call arguments and overload-resolution rules","C. They must belong to different classes","D. They cannot use default arguments"],"ans":"B","explanation":"Overload resolution considers argument types, conversions, and other language rules."},{"q":"A static data member belongs primarily to:","opts":["A. Each individual object separately","B. The class, with one shared member for that class (subject to the definition and storage rules)","C. Only the constructor's local scope","D. Every derived object as a separate copy of the base static member"],"ans":"B","explanation":"A static data member is shared by instances of the class rather than duplicated per object."},{"q":"Which statement about a static member function is correct?","opts":["A. It has a `this` pointer","B. It can directly access non-static members without an object","C. It has no `this` pointer and cannot directly access non-static members without an object","D. It must be virtual"],"ans":"C","explanation":"Static member functions are not invoked on a particular object and have no `this` pointer."},{"q":"What is the difference between a copy constructor and a copy-assignment operator?","opts":["A. There is no difference","B. A copy constructor initializes a new object from another; copy assignment assigns to an already-existing object","C. A copy constructor destroys objects","D. Copy assignment only works with integers"],"ans":"B","explanation":"Construction and assignment are distinct operations in C++."},{"q":"What is the Rule of Three in C++?","opts":["A. A class must have three constructors","B. If a class needs a custom destructor, copy constructor, or copy-assignment operator for resource management, it often needs all three","C. Every class must use three base classes","D. Every method must have three parameters"],"ans":"B","explanation":"The Rule of Three is a resource-management guideline for classes managing ownership manually."},{"q":"What does the Rule of Five add to the Rule of Three?","opts":["A. Two virtual functions","B. Move constructor and move-assignment operator","C. Two destructors","D. Two friend classes"],"ans":"B","explanation":"The Rule of Five includes move operations in addition to the destructor and copy operations."},{"q":"What is the main benefit of move semantics?","opts":["A. It always duplicates all resources","B. It can transfer resources from a temporary or expiring object instead of making an expensive deep copy","C. It removes the need for types","D. It makes every function virtual"],"ans":"B","explanation":"Move operations can transfer ownership of resources efficiently."},{"q":"Which SOLID principle says a class should have one reason to change?","opts":["A. Open/Closed Principle","B. Single Responsibility Principle","C. Liskov Substitution Principle","D. Dependency Inversion Principle"],"ans":"B","explanation":"SRP encourages each class to have one focused responsibility."},{"q":"Which SOLID principle encourages software entities to be open for extension but closed for modification?","opts":["A. Open/Closed Principle","B. Interface Segregation Principle","C. Single Responsibility Principle","D. Liskov Substitution Principle"],"ans":"A","explanation":"OCP aims to allow new behavior through extension without repeatedly modifying stable code."},{"q":"A class implementing an interface is forced to provide many methods it does not use. Which SOLID principle is most relevant?","opts":["A. Dependency Inversion","B. Interface Segregation","C. Open/Closed","D. Liskov Substitution"],"ans":"B","explanation":"ISP favors focused interfaces rather than large interfaces that burden clients."},{"q":"High-level business logic directly constructs a specific low-level database class, making testing difficult. Which principle suggests depending on abstractions?","opts":["A. Dependency Inversion Principle","B. Single Responsibility Principle","C. Interface Segregation Principle","D. Encapsulation only"],"ans":"A","explanation":"DIP encourages high-level and low-level modules to depend on abstractions."},{"q":"A subclass changes a method so that clients relying on the base class no longer work correctly. Which principle is violated?","opts":["A. Open/Closed","B. Liskov Substitution","C. Interface Segregation","D. Single Responsibility"],"ans":"B","explanation":"A subtype should preserve the behavioral contract expected from its base type."},{"q":"Which pattern provides a single shared instance through a controlled access point?","opts":["A. Observer","B. Singleton","C. Strategy","D. Adapter"],"ans":"B","explanation":"Singleton restricts a class to one instance and provides a way to access it."},{"q":"Which pattern allows an object to change its behavior by using a replaceable family of algorithms?","opts":["A. Strategy","B. Singleton","C. Factory Method only","D. Composite"],"ans":"A","explanation":"Strategy encapsulates interchangeable algorithms behind a common interface."},{"q":"Which pattern notifies dependent objects when a subject's state changes?","opts":["A. Adapter","B. Observer","C. Singleton","D. Builder"],"ans":"B","explanation":"Observer defines a subscription mechanism for notifying dependents of changes."},{"q":"Which pattern helps create objects while hiding or centralizing concrete construction choices?","opts":["A. Factory Method","B. Observer","C. Decorator only","D. Iterator"],"ans":"A","explanation":"Factory Method delegates object creation to a method or subclass rather than hard-coding a concrete type at every call site."},{"q":"A system needs to add responsibilities to an object dynamically without changing its class. Which pattern fits best?","opts":["A. Decorator","B. Singleton","C. Observer","D. Prototype only"],"ans":"A","explanation":"Decorator wraps an object and adds behavior while preserving a compatible interface."},{"q":"Why should a base class destructor be virtual when the class is intended for polymorphic deletion?","opts":["A. So its constructor can be overridden","B. So deleting through a base pointer destroys the complete derived object correctly","C. So all methods become private","D. So copying becomes impossible"],"ans":"B","explanation":"Virtual destruction ensures derived cleanup runs when deletion occurs through a base pointer."},{"q":"What is the main advantage of programming to an interface rather than a concrete implementation?","opts":["A. It prevents all bugs","B. It reduces coupling and makes implementations easier to substitute","C. It eliminates the need for testing","D. It forces inheritance in every class"],"ans":"B","explanation":"Clients depend on a contract rather than a specific implementation, improving flexibility and testability."},{"q":"Which approach usually improves testability for a service that sends notifications?","opts":["A. Construct a concrete email sender inside every method","B. Depend on a notification interface and inject the implementation","C. Use global mutable state for every notification","D. Make every function static"],"ans":"B","explanation":"Dependency injection allows tests to supply a fake or mock implementation."},{"q":"What is printed? `class A{public:int x=1;}; int main(){A a; A b=a; b.x=9; cout<<a.x<<b.x;}`","opts":["A. 19","B. 91","C. 99","D. Compilation error"],"ans":"A","explanation":"The default copy copies x by value. Changing b.x does not change a.x, so output is 19."},{"q":"What is printed? `class A{public: static int n; A(){++n;}}; int A::n=0; int main(){A x,y; cout<<A::n;}`","opts":["A. 0","B. 1","C. 2","D. Compilation error"],"ans":"C","explanation":"The constructor increments the shared static member once for each of the two objects."},{"q":"What is printed? `struct Base{Base(){cout<<\"B\";}}; struct Derived:Base{Derived(){cout<<\"D\";}}; int main(){Derived x;}`","opts":["A. DB","B. BD","C. D only","D. Compilation error"],"ans":"B","explanation":"The base class is constructed before the derived constructor body."},{"q":"What is printed? `struct A{~A(){cout<<\"A\";}}; struct B{~B(){cout<<\"B\";}}; int main(){A a; B b;}`","opts":["A. AB","B. BA","C. AABB","D. No output"],"ans":"B","explanation":"Local objects are destroyed in reverse order of construction, so b is destroyed before a."},{"q":"What happens here? `class Shape{public: virtual void draw()=0;}; int main(){Shape s;}`","opts":["A. It prints nothing but works","B. It creates an abstract object","C. Compilation fails because an abstract class cannot be instantiated directly","D. The pure virtual function is called automatically"],"ans":"C","explanation":"A class with a pure virtual function is abstract and cannot be instantiated directly."},{"q":"What happens when `Base* p = new Derived; delete p;` is used and `Base` has a non-virtual destructor?","opts":["A. It is always fully safe","B. It is undefined behavior in this polymorphic deletion scenario","C. It always calls both destructors correctly","D. It is a compile-time error in all cases"],"ans":"B","explanation":"Deleting a derived object through a base pointer with a non-virtual base destructor is undefined behavior."},{"q":"What is printed? `void f(int){cout<<\"I\";} void f(double){cout<<\"D\";} int main(){f(5); f(5.0);}`","opts":["A. ID","B. DI","C. II","D. DD"],"ans":"A","explanation":"An int argument selects f(int), and a double argument selects f(double)."},{"q":"What is printed? `class A{public:void f(){cout<<\"A\";}}; class B:public A{public:void f(){cout<<\"B\";}}; int main(){B b; b.f();}`","opts":["A. A","B. B","C. AB","D. Compilation error"],"ans":"B","explanation":"The member lookup on an object of type B finds B::f; virtual dispatch is not needed for this direct call."},{"q":"A class has private `int age` and a public method that rejects values below zero. Which property does the validation most directly preserve?","opts":["A. The class invariant","B. Multiple inheritance","C. Operator precedence","D. Object slicing"],"ans":"A","explanation":"A class invariant is a condition that should remain true for every valid object."},{"q":"A function accepts `const Shape& s` and calls a const-qualified virtual `draw()`. What does the reference help achieve?","opts":["A. It always copies the shape","B. It avoids slicing and can preserve runtime polymorphism","C. It makes Shape concrete","D. It disables virtual dispatch"],"ans":"B","explanation":"A reference avoids copying the object as a base value and allows virtual dispatch; const qualification requires a const-compatible function."},{"q":"A shopping cart must support adding items, removing items and calculating a total without allowing callers to corrupt its item list. Which design is best?","opts":["A. Publicly expose the mutable item list","B. Keep the list private and provide controlled public operations","C. Store the list in a global variable","D. Make every operation a friend function"],"ans":"B","explanation":"A private representation with controlled operations protects invariants and encapsulates implementation."},{"q":"You need to support new shipping methods without editing a large conditional statement every time. Which design is most suitable?","opts":["A. Use a common shipping interface with separate implementations","B. Put all shipping behavior in public global variables","C. Duplicate the whole checkout system for each method","D. Make shipping methods unrelated and uncallable through a common type"],"ans":"A","explanation":"Polymorphism and the Open/Closed Principle let new implementations be added behind a stable interface."}]},{"name":"OOPs — Output & Errors","icon":"</>","description":"Output prediction and find-the-error practice","questions":[{"q":"What is the output?\n```cpp\n#include <iostream>\nusing namespace std;\nclass A { public: A(){ cout << \"A\"; } };\nint main(){ A x; A y; }\n```","opts":["A. A","B. AA","C. AAA","D. Compilation error"],"ans":"B","explanation":"Each object construction calls the constructor once, so the output is AA."},{"q":"What is the output?\n```cpp\n#include <iostream>\nusing namespace std;\nclass Box { public: int n; Box(int x): n(x) {} };\nint main(){ Box b(4); cout << b.n; }\n```","opts":["A. 0","B. 4","C. Garbage value","D. Compilation error"],"ans":"B","explanation":"The member initializer list initializes n to the argument 4."},{"q":"What is wrong with this code?\n```cpp\nclass Test { public: Test(int x) {} };\nint main(){ Test t; }\n```","opts":["A. No error","B. A default constructor is unavailable","C. Constructors cannot take parameters","D. Class objects cannot be local variables"],"ans":"B","explanation":"Declaring a parameterized constructor prevents the compiler from automatically generating a default constructor."},{"q":"What is the output?\n```cpp\n#include <iostream>\nusing namespace std;\nclass A { public: ~A(){ cout << \"X\"; } };\nint main(){ A a; cout << \"Y\"; }\n```","opts":["A. XY","B. YX","C. X only","D. Compilation error"],"ans":"A","explanation":"The body prints Y first; the local object's destructor prints X when main exits."},{"q":"What is the output?\n```cpp\n#include <iostream>\nusing namespace std;\nclass A { public: int x=2; };\nint main(){ A a; A b=a; b.x=8; cout << a.x << b.x; }\n```","opts":["A. 28","B. 82","C. 88","D. Compilation error"],"ans":"A","explanation":"The implicitly generated copy constructor copies x by value, so changing b does not change a."},{"q":"What happens here?\n```cpp\nclass Account { private: int balance=10; };\nint main(){ Account a; a.balance=20; }\n```","opts":["A. Runs successfully","B. Prints 20","C. Compilation error: balance is private","D. Runtime error only"],"ans":"C","explanation":"Private members cannot be accessed directly from main."},{"q":"What is the error in this code?\n```cpp\nclass A { int x=5; };\nint main(){ A a; cout << a.x; }\n```","opts":["A. x is public by default","B. x is private by default in a class","C. Objects cannot contain integers","D. cout cannot print integers"],"ans":"B","explanation":"Class members are private by default in C++."},{"q":"What is the output?\n```cpp\n#include <iostream>\nusing namespace std;\nclass A { public: static int count; A(){ ++count; } };\nint A::count=0;\nint main(){ A x, y, z; cout << A::count; }\n```","opts":["A. 0","B. 1","C. 2","D. 3"],"ans":"D","explanation":"The static member is shared by all instances and increments once per constructor call."},{"q":"What is the output?\n```cpp\n#include <iostream>\nusing namespace std;\nclass A { public: static int n; };\nint A::n=7;\nint main(){ A a,b; a.n=9; cout << b.n; }\n```","opts":["A. 7","B. 9","C. 0","D. Compilation error"],"ans":"B","explanation":"Static data is shared, so changing a.n also changes the value observed through b.n."},{"q":"Which statement causes a compile-time error?\n```cpp\nclass A { public: static void f() {} int x=3; };\n```","opts":["A. The class declaration itself","B. Calling A::f()","C. Inside f, directly writing cout << x; without an object","D. Creating A a;"],"ans":"C","explanation":"A static member function has no this pointer and cannot directly access a non-static member."},{"q":"What is the output?\n```cpp\n#include <iostream>\nusing namespace std;\nclass Base { public: Base(){ cout << \"B\"; } };\nclass Derived: public Base { public: Derived(){ cout << \"D\"; } };\nint main(){ Derived d; }\n```","opts":["A. DB","B. BD","C. D","D. B"],"ans":"B","explanation":"The base class constructor runs before the derived class constructor body."},{"q":"What is the output?\n```cpp\n#include <iostream>\nusing namespace std;\nclass A { public: void show(){ cout << \"A\"; } };\nclass B: public A { public: void show(){ cout << \"B\"; } };\nint main(){ B obj; obj.show(); }\n```","opts":["A. A","B. B","C. AB","D. Compilation error"],"ans":"B","explanation":"The call is made on a B object, and B::show hides the base version for this call."},{"q":"What is the output?\n```cpp\n#include <iostream>\nusing namespace std;\nclass A { public: virtual void show(){ cout << \"A\"; } };\nclass B: public A { public: void show() override { cout << \"B\"; } };\nint main(){ B b; A* p=&b; p->show(); }\n```","opts":["A. A","B. B","C. AB","D. Compilation error"],"ans":"B","explanation":"Because show is virtual, dynamic dispatch calls B::show for the derived object."},{"q":"What is wrong?\n```cpp\nclass Base { private: int x=1; };\nclass Child: public Base { public: int get(){ return x; } };\n```","opts":["A. No error","B. Child cannot directly access Base's private member x","C. Inheritance is illegal in C++","D. get must be static"],"ans":"B","explanation":"A derived class cannot directly access private members declared in its base class."},{"q":"What is the output?\n```cpp\n#include <iostream>\nusing namespace std;\nclass A { public: ~A(){ cout << \"A\"; } };\nclass B { public: ~B(){ cout << \"B\"; } };\nint main(){ A a; B b; }\n```","opts":["A. AB","B. BA","C. AABB","D. No output"],"ans":"B","explanation":"Local objects are destroyed in reverse order of construction."},{"q":"What is the output?\n```cpp\n#include <iostream>\nusing namespace std;\nvoid f(int){ cout << \"I\"; }\nvoid f(double){ cout << \"D\"; }\nint main(){ f(3); f(3.0); }\n```","opts":["A. ID","B. DI","C. II","D. DD"],"ans":"A","explanation":"An int argument selects f(int); a double argument selects f(double)."},{"q":"Why is this invalid C++?\n```cpp\nint calc(int x){ return x; }\ndouble calc(int x){ return x; }\n```","opts":["A. Functions cannot be named calc","B. Functions cannot be overloaded by return type alone","C. int and double are identical types","D. Every function must be virtual"],"ans":"B","explanation":"The parameter lists are identical, so the return type alone cannot distinguish overloads."},{"q":"What is the output?\n```cpp\n#include <iostream>\nusing namespace std;\nclass N { public: int x; N(int v):x(v){} N operator+(const N& o){ return N(x+o.x); } };\nint main(){ N a(2), b(5); N c=a+b; cout << c.x; }\n```","opts":["A. 2","B. 5","C. 7","D. Compilation error"],"ans":"C","explanation":"The overloaded + operator returns a new N whose x is the sum, 2 + 5."},{"q":"Which operator cannot be overloaded in C++? ","opts":["A. +","B. ==","C. []","D. ::"],"ans":"D","explanation":"The scope-resolution operator :: cannot be overloaded."},{"q":"What is the output?\n```cpp\n#include <iostream>\nusing namespace std;\nclass A { public: virtual void f(){ cout << 1; } };\nclass B: public A { public: void f() override { cout << 2; } };\nint main(){ B b; A& r=b; r.f(); }\n```","opts":["A. 1","B. 2","C. 12","D. Compilation error"],"ans":"B","explanation":"A base reference to a derived object calls the derived override when the function is virtual."},{"q":"What happens?\n```cpp\nclass Shape { public: virtual void draw()=0; };\nint main(){ Shape s; }\n```","opts":["A. It works","B. Shape is abstract and cannot be instantiated","C. draw runs automatically","D. Only a warning"],"ans":"B","explanation":"A class with a pure virtual function is abstract and cannot be instantiated directly."},{"q":"What is the key issue with this design?\n```cpp\nclass Base { public: ~Base() {} };\nclass Derived: public Base {};\nint main(){ Base* p=new Derived; delete p; }\n```","opts":["A. Base must have a virtual destructor for safe polymorphic deletion","B. Derived cannot inherit Base","C. new cannot allocate derived objects","D. delete is forbidden for pointers"],"ans":"A","explanation":"Deleting a derived object through a base pointer when the base destructor is non-virtual causes undefined behavior."},{"q":"What is the output?\n```cpp\n#include <iostream>\nusing namespace std;\nclass A { public: virtual void f(){ cout << \"A\"; } };\nclass B: public A { public: void f() override { cout << \"B\"; } };\nint main(){ B b; A a=b; a.f(); }\n```","opts":["A. A","B. B","C. AB","D. Compilation error"],"ans":"A","explanation":"Copying a derived object into a base object by value slices off the derived portion; a is a base object."},{"q":"Which line fails to compile?\n```cpp\nclass Device { public: virtual void run()=0; };\nclass Phone: public Device {};\nint main(){ Phone p; }\n```","opts":["A. Device declaration","B. Phone declaration","C. Phone p;","D. No line fails"],"ans":"C","explanation":"Phone does not implement the inherited pure virtual function, so it remains abstract and cannot be instantiated."},{"q":"A class `Counter` starts with value 0. Its `increment()` method adds 1. Pseudocode creates two Counter objects, calls increment twice on the first and once on the second, then prints both values. What is printed?","opts":["A. 2 1","B. 3 3","C. 1 2","D. 0 0"],"ans":"A","explanation":"Each object has its own instance state, so the first holds 2 and the second holds 1."},{"q":"Pseudocode defines `setAge(x)` to update age only if x >= 0. Starting age is 20, then calls `setAge(-3)` and prints age. What prints?","opts":["A. -3","B. 0","C. 20","D. Error always"],"ans":"C","explanation":"The invalid update is rejected, so age remains 20."},{"q":"Class Vehicle has method move() printing `move`. Class Car inherits Vehicle and adds honk() printing `beep`. A Car object calls move() then honk(). What is printed?","opts":["A. movebeep","B. beepmove","C. move only","D. Compilation error"],"ans":"A","explanation":"The derived object can use the inherited public method and its own method."},{"q":"Base has virtual speak() printing `base`; Dog overrides it to print `dog`. A Base pointer refers to a Dog object and calls speak(). What is printed?","opts":["A. base","B. dog","C. basedog","D. Nothing"],"ans":"B","explanation":"Virtual dispatch selects the override for the actual object type."},{"q":"A House object owns a Room object as a member. When the House object is destroyed, what normally happens to its Room member?","opts":["A. The member's lifetime ends as part of destroying House","B. Room automatically becomes global","C. Room is always leaked","D. Room becomes a base class"],"ans":"A","explanation":"A member subobject is destroyed when its containing object is destroyed."},{"q":"What is wrong with this code?\n```cpp\nclass A { public: void f() {} };\nvoid g(const A& a){ a.f(); }\n```","opts":["A. A reference cannot be const","B. f is not declared const, so it cannot be called on a const A object","C. All methods must be static","D. g must return A"],"ans":"B","explanation":"A const object can call only const-qualified member functions."},{"q":"What is the output?\n```cpp\n#include <iostream>\nusing namespace std;\nclass A { public: int get() const { return 6; } };\nint main(){ const A a; cout << a.get(); }\n```","opts":["A. 0","B. 6","C. Compilation error","D. Garbage value"],"ans":"B","explanation":"The const-qualified get() method can be called on a const object and returns 6."},{"q":"What is wrong?\n```cpp\nclass A {};\nint main(){ A a; A& r; r=a; }\n```","opts":["A. References must be initialized when declared","B. Classes cannot be empty","C. References cannot refer to objects","D. r must be a pointer"],"ans":"A","explanation":"A C++ reference must be initialized at the point of declaration."},{"q":"What is the output?\n```cpp\n#include <iostream>\nusing namespace std;\nclass A { public: A(){cout<<\"C\";} A(const A&){cout<<\"K\";} };\nint main(){ A a; A b=a; }\n```","opts":["A. CC","B. CK","C. KC","D. K only"],"ans":"B","explanation":"Creating a uses the default constructor (C); initializing b from a uses the copy constructor (K)."},{"q":"Which declaration is the conventional copy constructor signature? ","opts":["A. A(A other)","B. A(const A& other)","C. void A(const A&)","D. A* A(const A&)"],"ans":"B","explanation":"A copy constructor typically accepts a reference to the same type, commonly const A&."},{"q":"What is printed?\n```cpp\n#include <iostream>\nusing namespace std;\nclass A { public: int x=1; };\nint main(){ A a,b; b.x=5; a=b; cout<<a.x; }\n```","opts":["A. 1","B. 5","C. 0","D. Compilation error"],"ans":"B","explanation":"The implicitly generated copy-assignment operator copies the member value from b to a."},{"q":"Class Ticket has a static variable issued initially 0. Each constructor increments issued. Pseudocode creates four Ticket objects and prints issued. What is printed?","opts":["A. 0","B. 1","C. 3","D. 4"],"ans":"D","explanation":"The static variable is shared and incremented once for each constructed object."},{"q":"Which statement is correct about a friend function? ","opts":["A. It becomes a class member automatically","B. It can access private members if declared as a friend, but remains a non-member","C. Every function is a friend","D. Friendship is always inherited"],"ans":"B","explanation":"Friendship grants access but does not make the function a member and is not inherited automatically."},{"q":"What is printed?\n```cpp\n#include <iostream>\nusing namespace std;\nclass A { public: void f(int){ cout<<\"A\"; } };\nclass B: public A { public: void f(double){ cout<<\"B\"; } };\nint main(){ B b; b.f(1); }\n```","opts":["A. A","B. B","C. AB","D. Compilation error"],"ans":"B","explanation":"B::f hides the base overload during name lookup; the int argument converts to double and calls B::f."},{"q":"What is wrong?\n```cpp\nclass A { public: virtual void f() {} };\nclass B: public A { public: void f(int) override {} };\n```","opts":["A. Nothing; it overrides A::f","B. override is invalid because the parameter list does not match the base virtual function","C. Virtual functions cannot be inherited","D. B cannot define methods"],"ans":"B","explanation":"The signature f(int) does not override f(); the override specifier correctly causes a compile-time error."},{"q":"What is the output?\n```cpp\n#include <iostream>\nusing namespace std;\nclass A { public: A(){cout<<\"A\";} };\nclass B { public: B(){cout<<\"B\";} };\nclass C { A a; B b; public: C(){cout<<\"C\";} };\nint main(){ C c; }\n```","opts":["A. ABC","B. BAC","C. CAB","D. CBA"],"ans":"A","explanation":"Members initialize in their declaration order (a then b), before the constructor body."},{"q":"A `Remote` object offers `pressPower()` while hiding the device's internal startup sequence. Which concept does this illustrate?","opts":["A. Abstraction","B. Object slicing","C. Multiple inheritance","D. Overloading"],"ans":"A","explanation":"The user interacts through a simple operation without needing internal implementation details."},{"q":"Pseudocode defines `print(int)` to output `I` and `print(string)` to output `S`. Calls `print(10)` then `print(\"hi\")`. What is output?","opts":["A. IS","B. SI","C. II","D. SS"],"ans":"A","explanation":"The overload is selected based on the argument type."},{"q":"What happens?\n```cpp\nclass A { protected: int x=3; };\nint main(){ A a; cout << a.x; }\n```","opts":["A. Prints 3","B. Compilation error: protected member is inaccessible from main","C. Prints 0","D. Runtime error"],"ans":"B","explanation":"Protected members are not accessible from unrelated non-member code through an object."},{"q":"What is printed?\n```cpp\n#include <iostream>\nusing namespace std;\nclass A { public: virtual void f(){cout<<\"A\";} };\nclass B: public A { public: void f() override {cout<<\"B\";} };\nvoid call(A* p){ p->f(); }\nint main(){ B b; call(&b); }\n```","opts":["A. A","B. B","C. AB","D. Compilation error"],"ans":"B","explanation":"The base pointer refers to a B object, so the virtual call invokes B::f."},{"q":"Pseudocode creates object A with value 3 and object B with value 3. It changes A's value to 10, then prints B's value. What is printed?","opts":["A. 3","B. 10","C. 13","D. Undefined"],"ans":"A","explanation":"Independent objects maintain separate instance state."},{"q":"What is wrong with this code?\n```cpp\nclass A { public: virtual void f()=0; };\nclass B: public A {};\nint main(){ B b; }\n```","opts":["A. B is still abstract because it does not implement f()","B. Pure virtual functions cannot be inherited","C. A must be a struct","D. The destructor is missing"],"ans":"A","explanation":"B inherits the unimplemented pure virtual function, so B remains abstract and cannot be instantiated."},{"q":"Assume both destructors are virtual. What is the output?\n```cpp\n#include <iostream>\nusing namespace std;\nclass A { public: virtual ~A(){cout<<\"A\";} };\nclass B: public A { public: ~B(){cout<<\"B\";} };\nint main(){ B b; }\n```","opts":["A. AB","B. BA","C. B only","D. A only"],"ans":"B","explanation":"The derived destructor runs before the base destructor."},{"q":"A class handles user login, database queries, and email sending. Which design principle most clearly suggests splitting these responsibilities?","opts":["A. Single Responsibility Principle","B. Liskov Substitution Principle","C. Interface Segregation Principle","D. Singleton"],"ans":"A","explanation":"The Single Responsibility Principle encourages a class to have one focused reason to change."},{"q":"A checkout service accepts a `PaymentMethod` interface instead of creating a concrete card processor itself. What is the main benefit?","opts":["A. Tighter coupling","B. Easier substitution and testing","C. No need for objects","D. All errors disappear"],"ans":"B","explanation":"Depending on an abstraction reduces coupling and lets tests or other payment implementations be injected."},{"q":"What is the output?\n```cpp\n#include <iostream>\nusing namespace std;\nclass Point { public: int x; Point(int n):x(n){} };\nint main(){ Point p(4); Point q=p; q.x=7; cout<<p.x; }\n```","opts":["A. 4","B. 7","C. 11","D. Compilation error"],"ans":"A","explanation":"The default copy copies the integer member by value, so modifying q does not change p."}]},{"name":"Pseudocode — Placement Practice","icon":"λ","description":"Loops, bitwise, arrays, functions, recursion and pointers","questions":[{"q":"What is the output?\n```text\na = 7\nb = 2\nprint(a / b)\nprint(a // b)\n```","opts":["A. 3.5 then 3","B. 3 then 3.5","C. 3.5 then 3.5","D. 3 then 3"],"ans":"A","explanation":"Ordinary division gives 3.5; integer floor division gives 3."},{"q":"What is the output?\n```text\nx = 5\ny = x++\nprint(x, y)\n```","opts":["A. 5 5","B. 6 5","C. 6 6","D. 5 6"],"ans":"B","explanation":"Post-increment uses the old value in the expression, then increments x."},{"q":"What is the output?\n```text\nx = 5\ny = ++x\nprint(x, y)\n```","opts":["A. 5 5","B. 6 5","C. 6 6","D. 5 6"],"ans":"C","explanation":"Pre-increment increments x first, so both x and y are 6."},{"q":"What is the output?\n```text\nprint(10 - 3 * 2 + 4)\n```","opts":["A. 18","B. 8","C. 14","D. 4"],"ans":"B","explanation":"Multiplication happens first: 10 - 6 + 4 = 8."},{"q":"Assume C/C++ remainder rules. What is the output?\n```text\nprint(-13 % 5)\n```","opts":["A. -3","B. 2","C. 3","D. -2"],"ans":"A","explanation":"In C/C++, integer division truncates toward zero, so -13 % 5 is -3."},{"q":"What is the output?\n```text\nx = 4\nx = x + 3 * 2\nx = x - 5\nprint(x)\n```","opts":["A. 3","B. 5","C. 6","D. 10"],"ans":"B","explanation":"First x becomes 10, then 5."},{"q":"What is the output?\n```text\na = 8\nb = 3\nprint(a % b + a // b)\n```","opts":["A. 3","B. 4","C. 5","D. 6"],"ans":"C","explanation":"8 % 3 is 2 and 8 // 3 is 2, so the sum is 4."},{"q":"What is the output?\n```text\ns = 0\nfor i = 1 to 4:\n    s = s + i\nprint(s)\n```","opts":["A. 6","B. 10","C. 4","D. 11"],"ans":"B","explanation":"The loop adds 1 + 2 + 3 + 4 = 10."},{"q":"How many times does `print(i)` execute?\n```text\nfor i = 0; i < 10; i = i + 2:\n    print(i)\n```","opts":["A. 4","B. 5","C. 6","D. 10"],"ans":"B","explanation":"The values are 0, 2, 4, 6, 8: five iterations."},{"q":"What is the output?\n```text\nx = 1\nwhile x < 20:\n    x = x * 2\nprint(x)\n```","opts":["A. 16","B. 20","C. 32","D. 64"],"ans":"C","explanation":"x progresses 1, 2, 4, 8, 16, 32; the loop stops at 32."},{"q":"What is the output?\n```text\ns = 0\nfor i = 1 to 5:\n    if i == 3: continue\n    s = s + i\nprint(s)\n```","opts":["A. 12","B. 15","C. 9","D. 8"],"ans":"A","explanation":"The loop skips 3, so 1 + 2 + 4 + 5 = 12."},{"q":"What is the output?\n```text\ns = 0\nfor i = 1 to 6:\n    if i == 5: break\n    s = s + i\nprint(s)\n```","opts":["A. 15","B. 10","C. 11","D. 21"],"ans":"B","explanation":"The loop stops before adding 5: 1 + 2 + 3 + 4 = 10."},{"q":"What is the output? (Assume integer division.)\n```text\nx = 100\ncount = 0\nwhile x > 1:\n    x = x // 2\n    count = count + 1\nprint(count)\n```","opts":["A. 5","B. 6","C. 7","D. 8"],"ans":"B","explanation":"The values become 50, 25, 12, 6, 3, 1, so the loop runs 6 times."},{"q":"What is the output?\n```text\nfor i = 1 to 3:\n    for j = 1 to 2:\n        print(i + j)\n```","opts":["A. 2 3 3 4 4 5","B. 1 2 2 3 3 4","C. 2 2 3 3 4 4","D. 3 4 4 5 5 6"],"ans":"A","explanation":"For each i, j takes 1 and 2, producing 2, 3, 3, 4, 4, 5."},{"q":"How many times is `*` printed?\n```text\nfor i = 1 to 4:\n    for j = 1 to i:\n        print(\"*\")\n```","opts":["A. 4","B. 6","C. 8","D. 10"],"ans":"D","explanation":"The inner loop runs 1 + 2 + 3 + 4 = 10 times."},{"q":"What is the output?\n```text\nx = 12\nif x > 10:\n    if x < 15: print(\"A\")\n    else: print(\"B\")\nelse: print(\"C\")\n```","opts":["A. A","B. B","C. C","D. AB"],"ans":"A","explanation":"Both conditions x > 10 and x < 15 are true."},{"q":"What is the output?\n```text\nx = 4\ny = 9\nif x > 5 AND y > 5:\n    print(1)\nelse:\n    print(2)\n```","opts":["A. 1","B. 2","C. 9","D. No output"],"ans":"B","explanation":"The AND condition is false because x > 5 is false."},{"q":"What is the output?\n```text\nx = 4\ny = 9\nif x > 5 OR y > 5:\n    print(1)\nelse:\n    print(2)\n```","opts":["A. 1","B. 2","C. 4","D. No output"],"ans":"A","explanation":"The OR condition is true because y > 5 is true."},{"q":"What is the output?\n```text\nn = 7\nprint(\"even\" if n % 2 == 0 else \"odd\")\n```","opts":["A. even","B. odd","C. 7","D. Error"],"ans":"B","explanation":"7 % 2 is 1, so n is odd."},{"q":"What is the output?\n```text\nx = 6\nif (x & 1) == 0: print(\"E\")\nelse: print(\"O\")\n```","opts":["A. E","B. O","C. 6","D. Error"],"ans":"A","explanation":"The least significant bit of 6 is 0, so it is even."},{"q":"What is the output?\n```text\nprint(5 XOR 3)\n```","opts":["A. 1","B. 6","C. 7","D. 8"],"ans":"B","explanation":"5 is 101 and 3 is 011; XOR gives 110, which is 6."},{"q":"What is the output?\n```text\nx = 9\nprint(x << 1)\n```","opts":["A. 9","B. 18","C. 4","D. 81"],"ans":"B","explanation":"For a non-negative integer, left shift by one position is equivalent to multiplying by 2."},{"q":"What is the output?\n```text\nx = 20\nprint(x >> 2)\n```","opts":["A. 10","B. 5","C. 4","D. 80"],"ans":"B","explanation":"Right-shifting 20 by two positions gives floor(20 / 4) = 5."},{"q":"What does this code print?\n```text\nn = 8\nif (n AND (n - 1)) == 0: print(\"YES\")\nelse: print(\"NO\")\n```","opts":["A. YES","B. NO","C. 8","D. 0"],"ans":"A","explanation":"A positive power of two has exactly one set bit, so n & (n - 1) is zero."},{"q":"What is the output?\n```text\nx = 10\nx = x XOR 6\nx = x XOR 6\nprint(x)\n```","opts":["A. 0","B. 6","C. 10","D. 12"],"ans":"C","explanation":"XORing the same value twice restores the original value."},{"q":"What is the output?\n```text\na = 5\nb = 9\na = a XOR b\nb = a XOR b\na = a XOR b\nprint(a, b)\n```","opts":["A. 5 9","B. 9 5","C. 12 12","D. 0 0"],"ans":"B","explanation":"The XOR swap exchanges the two values, so a becomes 9 and b becomes 5."},{"q":"What is the output?\n```text\nA = [3, 1, 7, 2]\ns = 0\nfor i = 0 to 3:\n    s = s + A[i]\nprint(s)\n```","opts":["A. 10","B. 11","C. 13","D. 14"],"ans":"C","explanation":"The sum is 3 + 1 + 7 + 2 = 13."},{"q":"What is the output?\n```text\nA = [4, 8, 2, 9, 5]\nm = A[0]\nfor i = 1 to 4:\n    if A[i] > m: m = A[i]\nprint(m)\n```","opts":["A. 4","B. 8","C. 9","D. 5"],"ans":"C","explanation":"The largest element in the array is 9."},{"q":"After this loop, what is A?\n```text\nA = [1, 2, 3, 4]\nfor i = 0 to 2:\n    swap(A[i], A[3-i])\n```","opts":["A. [4, 3, 2, 1]","B. [4, 2, 3, 1]","C. [1, 3, 2, 4]","D. [1, 2, 3, 4]"],"ans":"D","explanation":"The loop swaps indices 0 and 3, then 1 and 2, then swaps them back (indices 2 and 1), then swaps 3 and 0 if loop bounds are inclusive. This loop runs i=0..2 and returns the original array."},{"q":"After this loop, what is A?\n```text\nA = [1, 2, 3, 4]\nfor i = 0 to 1:\n    swap(A[i], A[3-i])\n```","opts":["A. [4, 3, 2, 1]","B. [4, 2, 3, 1]","C. [1, 3, 2, 4]","D. [1, 2, 3, 4]"],"ans":"A","explanation":"The loop swaps the first and last elements, then the middle pair, reversing the array."},{"q":"After one full left-to-right bubble-sort pass using adjacent swaps when A[j] > A[j+1], what is the array?\n```text\nA = [5, 1, 4, 2]\n```","opts":["A. [1, 4, 2, 5]","B. [1, 2, 4, 5]","C. [5, 1, 2, 4]","D. [2, 1, 4, 5]"],"ans":"A","explanation":"One pass moves the largest value to the end: [5,1,4,2] → [1,5,4,2] → [1,4,5,2] → [1,4,2,5]."},{"q":"What is the output?\n```text\nA = [[1,2,3], [4,5,6]]\nprint(A[1][0] + A[0][2])\n```","opts":["A. 7","B. 8","C. 9","D. 10"],"ans":"C","explanation":"A[1][0] is 4 and A[0][2] is 3, so the sum is 7."},{"q":"What is the output?\n```text\nA = [[1,2], [3,4]]\ns = 0\nfor i = 0 to 1:\n    s = s + A[i][i]\nprint(s)\n```","opts":["A. 4","B. 5","C. 6","D. 10"],"ans":"B","explanation":"The main diagonal contains 1 and 4, whose sum is 5."},{"q":"How many times does `count = count + 1` execute?\n```text\ncount = 0\nfor i = 0 to 2:\n    for j = 0 to 3:\n        count = count + 1\nprint(count)\n```","opts":["A. 7","B. 9","C. 12","D. 16"],"ans":"C","explanation":"There are 3 rows and 4 columns, so the inner statement executes 3 × 4 = 12 times."},{"q":"What is the output?\n```text\nfunction f(x):\n    x = x + 5\n    return x\nn = 3\nf(n)\nprint(n)\n```","opts":["A. 3","B. 8","C. 5","D. Error"],"ans":"A","explanation":"With pass-by-value, f modifies its local copy; n remains 3."},{"q":"What is the output?\n```text\nfunction f(x):\n    x = x + 5\n    return x\nprint(f(2) + f(3))\n```","opts":["A. 10","B. 15","C. 12","D. 5"],"ans":"A","explanation":"f(2) returns 7 and f(3) returns 8; their sum is 15."},{"q":"What is the output?\n```text\nx = 10\nfunction f():\n    x = 3\n    print(x)\nf()\nprint(x)\n```","opts":["A. 3 then 3","B. 10 then 3","C. 3 then 10","D. 10 then 10"],"ans":"C","explanation":"The local x inside f is 3; the global x remains 10."},{"q":"What is the output?\n```text\nfunction f(n):\n    if n == 0: return 0\n    return n + f(n-1)\nprint(f(4))\n```","opts":["A. 4","B. 6","C. 10","D. 24"],"ans":"C","explanation":"The function computes 4 + 3 + 2 + 1 + 0 = 10."},{"q":"What is the output?\n```text\nfunction f(x):\n    return x * 2\nfunction g(x):\n    return f(x + 1)\nprint(g(4))\n```","opts":["A. 8","B. 9","C. 10","D. 12"],"ans":"C","explanation":"g(4) calls f(5), which returns 10."},{"q":"What is the output?\n```text\nfunction f(n):\n    if n == 0: return\n    print(n)\n    f(n-1)\nf(3)\n```","opts":["A. 1 2 3","B. 3 2 1","C. 3 3 3","D. No output"],"ans":"B","explanation":"The number is printed before the recursive call, so the order is descending."},{"q":"What is the output?\n```text\nfunction f(n):\n    if n == 0: return\n    f(n-1)\n    print(n)\nf(3)\n```","opts":["A. 1 2 3","B. 3 2 1","C. 0 1 2 3","D. No output"],"ans":"A","explanation":"The print occurs after the recursive call, so values print while recursion unwinds."},{"q":"What does `f(5)` return?\n```text\nfunction f(n):\n    if n <= 1: return 1\n    return n * f(n-1)\n```","opts":["A. 15","B. 24","C. 120","D. 720"],"ans":"C","explanation":"This is factorial: 5 × 4 × 3 × 2 × 1 = 120."},{"q":"What is printed?\n```text\nfunction f(n):\n    if n == 0: return 0\n    return n % 10 + f(n // 10)\nprint(f(482))\n```","opts":["A. 8","B. 12","C. 14","D. 482"],"ans":"C","explanation":"The digit sum is 4 + 8 + 2 = 14."},{"q":"What does this function return for f(6)?\n```text\nfunction f(n):\n    if n <= 1: return n\n    return f(n-1) + f(n-2)\n```","opts":["A. 5","B. 6","C. 8","D. 13"],"ans":"C","explanation":"This is Fibonacci with f(0)=0 and f(1)=1, giving f(6)=8."},{"q":"How many times is `print(\"X\")` executed?\n```text\nfunction f(n):\n    if n == 0: return\n    print(\"X\")\n    f(n-1)\nf(4)\n```","opts":["A. 3","B. 4","C. 5","D. 8"],"ans":"B","explanation":"The function prints once for n = 4, 3, 2, 1; the base case n = 0 prints nothing."},{"q":"What is the output?\n```text\nfunction f(n):\n    if n == 0: return\n    print(n)\n    f(n-1)\n    print(n)\nf(2)\n```","opts":["A. 2 1 1 2","B. 2 1 2 1","C. 1 2 2 1","D. 2 2 1 1"],"ans":"A","explanation":"It prints 2, then 1, then prints 1 and 2 during unwinding."},{"q":"What does f(4) return?\n```text\nfunction f(n):\n    if n == 1: return 1\n    return n + f(n-1)\n```","opts":["A. 4","B. 6","C. 10","D. 24"],"ans":"C","explanation":"The recurrence sums 4 + 3 + 2 + 1 = 10."},{"q":"What is the output?\n```text\nx = 5\np = address of x\n*p = 12\nprint(x)\n```","opts":["A. 5","B. 12","C. Address of x","D. Error"],"ans":"B","explanation":"Dereferencing p accesses x, so assigning through p changes x to 12."},{"q":"What is the output?\n```text\nA = [10, 20, 30]\np = address of A[0]\nprint(*(p + 2))\n```","opts":["A. 10","B. 20","C. 30","D. Address of A[2]"],"ans":"C","explanation":"Pointer arithmetic advances by array elements, so p + 2 points to A[2], which is 30."},{"q":"What is the output?\n```text\nx = 3\ny = 8\np = address of x\nq = address of y\nswap(*p, *q)\nprint(x, y)\n```","opts":["A. 3 8","B. 8 3","C. 3 3","D. 8 8"],"ans":"B","explanation":"Swapping the values referenced by p and q exchanges x and y."}]},{"name":"Operating Systems","icon":"⚙","description":"100 placement MCQs across OS fundamentals, processes, scheduling, synchronisation, deadlocks, memory, paging and more","questions":[{"q":"A user program wants the OS to read a file for it. Which mechanism does it use to ask the kernel for this service?","opts":[{"label":"A","text":"A normal function call that jumps straight into kernel memory"},{"label":"B","text":"Writing directly to the disk controller's registers"},{"label":"C","text":"Editing the kernel's page table"},{"label":"D","text":"A system call, which traps into kernel mode"}],"ans":"D","explanation":"User code cannot jump into the kernel arbitrarily. A system call executes a trap instruction; the CPU switches to kernel mode and jumps to a fixed, OS-controlled handler."},{"q":"Which of the following instructions should be allowed only in kernel (privileged) mode?","opts":[{"label":"A","text":"Load a constant into a register"},{"label":"B","text":"Add two registers"},{"label":"C","text":"Read the system clock"},{"label":"D","text":"Disable interrupts"}],"ans":"D","explanation":"Disabling interrupts could let a user program hog the CPU forever, so it is privileged. Arithmetic, loads and reading the clock are harmless in user mode."},{"q":"Which statement about Linux and Ubuntu is correct?","opts":[{"label":"A","text":"Linux is a full distribution; Ubuntu is its kernel"},{"label":"B","text":"Linux is a kernel; Ubuntu is a distribution built around it"},{"label":"C","text":"Both are kernels"},{"label":"D","text":"The kernel is always a separate program from the operating system"}],"ans":"B","explanation":"Linux is just the kernel. Ubuntu = Linux kernel + shell, desktop, file manager, libraries and thousands of other programs."},{"q":"Which of the following is a synchronous event, i.e. caused directly by the instruction being executed?","opts":[{"label":"A","text":"Disk I/O completion signal"},{"label":"B","text":"Timer interrupt"},{"label":"C","text":"Keyboard key press"},{"label":"D","text":"Divide-by-zero exception"}],"ans":"D","explanation":"Exceptions/traps (divide by zero, illegal instruction, system call) are caused by the running instruction. Key presses, timer ticks and I/O completions are asynchronous hardware interrupts."},{"q":"Why is the hardware timer interrupt essential for a multitasking OS?","opts":[{"label":"A","text":"It makes memory accesses faster"},{"label":"B","text":"It lets user programs enter kernel mode whenever they like"},{"label":"C","text":"It is only used to display the wall-clock time"},{"label":"D","text":"It lets the OS take the CPU back from a process stuck in an endless user-mode loop"}],"ans":"D","explanation":"Without the timer, a process that never makes a system call would keep the CPU forever. The timer interrupt forces control back to the kernel so it can preempt and schedule someone else."},{"q":"Which of the following causes the CPU to switch from user mode to kernel mode?","opts":[{"label":"A","text":"Executing an add instruction"},{"label":"B","text":"Reading a local variable"},{"label":"C","text":"A device raising an interrupt"},{"label":"D","text":"Calling a function defined in the same program"}],"ans":"C","explanation":"Interrupts, exceptions and system calls are the ways control enters the kernel. Ordinary instructions and function calls stay in user mode."},{"q":"What is the correct order of events when a computer boots?","opts":[{"label":"A","text":"POST (firmware) → bootloader → kernel is loaded → init / first user process"},{"label":"B","text":"Kernel → POST → bootloader → init"},{"label":"C","text":"init → kernel → bootloader → POST"},{"label":"D","text":"Bootloader → POST → kernel → init"}],"ans":"A","explanation":"Firmware runs the power-on self-test, then hands over to the bootloader, which loads the kernel; the kernel then starts the first user-space process (init/systemd)."},{"q":"In a microkernel design:","opts":[{"label":"A","text":"All services (file system, drivers, networking) run inside the kernel"},{"label":"B","text":"There are no system calls"},{"label":"C","text":"Only minimal services run in the kernel; the rest run as user-space processes that communicate via IPC"},{"label":"D","text":"The kernel is replaced by a hypervisor"}],"ans":"C","explanation":"A microkernel keeps scheduling, basic memory management and IPC in the kernel. This improves reliability (a driver crash doesn't kill the kernel) at the cost of extra IPC overhead. A monolithic kernel runs everything in kernel space."},{"q":"In the standard five-state process model, which transition is NOT possible?","opts":[{"label":"A","text":"Ready → Running"},{"label":"B","text":"Running → Ready"},{"label":"C","text":"Waiting → Running"},{"label":"D","text":"Running → Waiting"}],"ans":"C","explanation":"When I/O finishes, a waiting process goes to Ready, not directly to Running. The scheduler then dispatches it."},{"q":"Which of the following is NOT shared among the threads of the same process?","opts":[{"label":"A","text":"Code section"},{"label":"B","text":"Global data"},{"label":"C","text":"Open files"},{"label":"D","text":"Stack"}],"ans":"D","explanation":"Each thread has its own stack (and registers/program counter). Code, global data, heap and open files are shared."},{"q":"A process has finished executing, but its entry stays in the process table because its parent has not yet called wait(). Such a process is called:","opts":[{"label":"A","text":"Zombie"},{"label":"B","text":"Daemon"},{"label":"C","text":"Deadlocked process"},{"label":"D","text":"Orphan"}],"ans":"A","explanation":"A zombie has terminated but is not yet reaped by its parent. An orphan is a child whose parent has terminated first (adopted by init)."},{"q":"How many child processes are created by this code? `fork(); fork(); fork(); fork();`","opts":[{"label":"A","text":"4"},{"label":"B","text":"8"},{"label":"C","text":"15"},{"label":"D","text":"16"}],"ans":"C","explanation":"Every fork() doubles the number of processes: 2^4 = 16 total, so 16 − 1 = 15 are children."},{"q":"How many processes exist in total (including the original) after this runs? `if (fork() && fork()) fork();`","opts":[{"label":"A","text":"3"},{"label":"B","text":"4"},{"label":"C","text":"6"},{"label":"D","text":"8"}],"ans":"B","explanation":"fork() returns 0 in the child and non-zero in the parent. The original creates C1 and, since the result is non-zero, evaluates the second fork (C2) and then the third fork (C3). C1 sees 0 and short-circuits; C2 sees 0 from the second fork and skips the third. Total = original + C1 + C2 + C3 = 4."},{"q":"How many times is X printed? `fork(); fork(); printf(\"X\");`","opts":[{"label":"A","text":"8"},{"label":"B","text":"4"},{"label":"C","text":"3"},{"label":"D","text":"2"}],"ans":"B","explanation":"Two forks give 2^2 = 4 processes, and each one executes the printf once."},{"q":"Total number of processes (including the original) created by: `fork(); if (fork()) fork();`","opts":[{"label":"A","text":"8"},{"label":"B","text":"6"},{"label":"C","text":"4"},{"label":"D","text":"3"}],"ans":"B","explanation":"The first fork() gives 2 processes. Each of them then runs `if (fork()) fork();`: it creates a child, and since the parent gets a non-zero value it forks once more. That is 3 processes per original, so 2 × 3 = 6."},{"q":"After fork(), the child process changes a local variable x. What does the parent see?","opts":[{"label":"A","text":"The original value, because the child works on its own copy of the address space (copy-on-write)"},{"label":"B","text":"The changed value, but only if x is global"},{"label":"C","text":"The changed value, because memory is shared after fork()"},{"label":"D","text":"A segmentation fault"}],"ans":"A","explanation":"fork() gives the child a separate address space (usually implemented with copy-on-write). Writes in one process are invisible to the other."},{"q":"What does a successful exec() call do?","opts":[{"label":"A","text":"Terminates the parent process"},{"label":"B","text":"Waits for a child to terminate"},{"label":"C","text":"Creates a new child process running the same program"},{"label":"D","text":"Replaces the calling process's code and data with a new program (the PID stays the same)"}],"ans":"D","explanation":"exec() does not create a process; it overwrites the current process image. That is why shells call fork() first and then exec() in the child."},{"q":"What does fork() return?","opts":[{"label":"A","text":"The parent's PID in both processes"},{"label":"B","text":"The child's PID in the child and 0 in the parent"},{"label":"C","text":"0 in the child and the child's PID in the parent (−1 on failure)"},{"label":"D","text":"Always 0"}],"ans":"C","explanation":"fork() returns 0 in the child and the child's PID in the parent, which lets the code tell the two apart. A return value of −1 means the call failed."},{"q":"Why is a context switch between two threads of the same process usually cheaper than between two different processes?","opts":[{"label":"A","text":"The address space stays the same, so no page-table switch or TLB flush is needed"},{"label":"B","text":"Threads have no stack"},{"label":"C","text":"Threads never need the kernel's scheduler"},{"label":"D","text":"Threads do not have registers"}],"ans":"A","explanation":"Threads of one process share the address space, so the MMU context stays valid and the TLB need not be flushed. Only registers, PC and stack pointer change."},{"q":"P1, P2, P3 have burst times 24, 3 and 3 ms. All arrive at time 0 in this order and FCFS is used. What is the average waiting time?","opts":[{"label":"A","text":"3 ms"},{"label":"B","text":"10 ms"},{"label":"C","text":"17 ms"},{"label":"D","text":"27 ms"}],"ans":"C","explanation":"Waiting times are 0, 24 and 27 ms. Average = 51 / 3 = 17 ms. This is the convoy effect: short jobs stuck behind a long one."},{"q":"Non-preemptive SJF with: P1 (AT 0, BT 7), P2 (AT 2, BT 4), P3 (AT 4, BT 1), P4 (AT 5, BT 4). What is the average waiting time?","opts":[{"label":"A","text":"3 ms"},{"label":"B","text":"4 ms"},{"label":"C","text":"5 ms"},{"label":"D","text":"7 ms"}],"ans":"B","explanation":"Order of execution: P1 (0–7), P3 (7–8), P2 (8–12), P4 (12–16). Waiting times: P1 0, P3 3, P2 6, P4 7. Sum = 16, average = 4 ms."},{"q":"Same processes as above (P1: AT 0, BT 7; P2: AT 2, BT 4; P3: AT 4, BT 1; P4: AT 5, BT 4), now scheduled with SRTF (preemptive SJF). What is the average waiting time?","opts":[{"label":"A","text":"3 ms"},{"label":"B","text":"4 ms"},{"label":"C","text":"4.5 ms"},{"label":"D","text":"6 ms"}],"ans":"A","explanation":"Gantt: P1 0–2, P2 2–4, P3 4–5, P2 5–7, P4 7–11, P1 11–16. Waiting = turnaround − burst: P1 9, P2 1, P3 0, P4 2. Sum = 12, average = 3 ms."},{"q":"Round Robin with time quantum 4 ms. P1 (BT 10), P2 (BT 5), P3 (BT 8) all arrive at time 0 in this order. At what time does P2 complete?","opts":[{"label":"A","text":"9 ms"},{"label":"B","text":"13 ms"},{"label":"C","text":"17 ms"},{"label":"D","text":"21 ms"}],"ans":"C","explanation":"Gantt: P1 0–4, P2 4–8, P3 8–12, P1 12–16, P2 16–17, P3 17–21, P1 21–23. P2 finishes at 17 ms."},{"q":"In Round Robin scheduling, if the time quantum is made larger than the longest CPU burst, the algorithm behaves like:","opts":[{"label":"A","text":"SRTF"},{"label":"B","text":"SJF"},{"label":"C","text":"Priority scheduling"},{"label":"D","text":"FCFS"}],"ans":"D","explanation":"With a huge quantum nobody is ever preempted, so processes simply run to completion in arrival order, which is FCFS."},{"q":"Which technique is used to prevent starvation of low-priority processes in priority scheduling?","opts":[{"label":"A","text":"Aging"},{"label":"B","text":"Increasing the time quantum"},{"label":"C","text":"Spooling"},{"label":"D","text":"Paging"}],"ans":"A","explanation":"Aging gradually raises the priority of a process the longer it waits, so it eventually gets the CPU."},{"q":"When all processes are available at the same time, which scheduling algorithm gives the minimum average waiting time?","opts":[{"label":"A","text":"Shortest Job First"},{"label":"B","text":"Round Robin"},{"label":"C","text":"FCFS"},{"label":"D","text":"Priority scheduling with arbitrary priorities"}],"ans":"A","explanation":"SJF is provably optimal for average waiting time, because running shorter jobs first reduces the waiting of everyone behind them."},{"q":"FCFS with: P1 (AT 0, BT 5), P2 (AT 1, BT 3), P3 (AT 2, BT 8), P4 (AT 3, BT 6). What is the average waiting time?","opts":[{"label":"A","text":"6.5 ms"},{"label":"B","text":"5.75 ms"},{"label":"C","text":"5.25 ms"},{"label":"D","text":"4.75 ms"}],"ans":"B","explanation":"Execution order is P1, P2, P3, P4. Start times 0, 5, 8, 16, so waiting = start − arrival = 0, 4, 6, 13. Sum = 23, average = 5.75 ms."},{"q":"Preemptive priority scheduling (smaller number = higher priority): P1 (AT 0, BT 4, priority 3), P2 (AT 1, BT 3, priority 1), P3 (AT 2, BT 2, priority 2). At what time does P1 complete?","opts":[{"label":"A","text":"10 ms"},{"label":"B","text":"9 ms"},{"label":"C","text":"7 ms"},{"label":"D","text":"6 ms"}],"ans":"B","explanation":"P1 runs 0–1, P2 preempts and runs 1–4, then P3 (priority 2) runs 4–6 ahead of P1 (priority 3), and P1 finishes its remaining 3 ms during 6–9."},{"q":"Round Robin with quantum 3 ms. All arrive at time 0 in the order P1 (BT 6), P2 (BT 3), P3 (BT 5). What is the average waiting time?","opts":[{"label":"A","text":"4 ms"},{"label":"B","text":"5 ms"},{"label":"C","text":"6 ms"},{"label":"D","text":"7 ms"}],"ans":"C","explanation":"Gantt: P1 0–3, P2 3–6, P3 6–9, P1 9–12, P3 12–14. Completion: P1 12, P2 6, P3 14. Waiting = completion − burst = 6, 3, 9. Sum = 18, average = 6 ms."},{"q":"A process arrives at t = 3 ms, has a CPU burst of 5 ms and completes at t = 20 ms (no I/O). What is its waiting time?","opts":[{"label":"A","text":"5 ms"},{"label":"B","text":"12 ms"},{"label":"C","text":"15 ms"},{"label":"D","text":"17 ms"}],"ans":"B","explanation":"Turnaround = completion − arrival = 20 − 3 = 17 ms. Waiting = turnaround − burst = 17 − 5 = 12 ms."},{"q":"Which scheduler automatically moves CPU-hungry processes to lower-priority queues, thereby favouring short and interactive jobs?","opts":[{"label":"A","text":"Multilevel Feedback Queue (MLFQ)"},{"label":"B","text":"Pure SJF"},{"label":"C","text":"FCFS"},{"label":"D","text":"Static priority scheduling"}],"ans":"A","explanation":"MLFQ demotes processes that use up their whole quantum and keeps I/O-bound/interactive ones in high-priority queues. Aging can be added to prevent starvation."},{"q":"Which of the following scheduling algorithms can cause starvation of long processes?","opts":[{"label":"A","text":"FCFS"},{"label":"B","text":"Round Robin"},{"label":"C","text":"SRTF"},{"label":"D","text":"None of them"}],"ans":"C","explanation":"A steady stream of short jobs keeps preempting a long one under SRTF. FCFS and Round Robin give every process a turn eventually."},{"q":"SJF burst prediction uses τ(n+1) = α·t(n) + (1 − α)·τ(n) with α = 0.5. Initial guess τ0 = 10 ms; actual bursts t0 = 6 ms and t1 = 4 ms. What is the prediction τ2?","opts":[{"label":"A","text":"5 ms"},{"label":"B","text":"6 ms"},{"label":"C","text":"7 ms"},{"label":"D","text":"8 ms"}],"ans":"B","explanation":"τ1 = 0.5 × 6 + 0.5 × 10 = 8. τ2 = 0.5 × 4 + 0.5 × 8 = 6 ms."},{"q":"In Round Robin the quantum is 8 ms and each context switch costs 2 ms. Assuming every process uses its full quantum, what fraction of CPU time is useful work?","opts":[{"label":"A","text":"60%"},{"label":"B","text":"75%"},{"label":"C","text":"80%"},{"label":"D","text":"90%"}],"ans":"C","explanation":"Useful fraction = q / (q + s) = 8 / (8 + 2) = 80%."},{"q":"Two threads each execute `count++` on a shared variable without synchronisation, and some updates get lost. Why?","opts":[{"label":"A","text":"count++ is a load–modify–store sequence that can be interleaved with the other thread's"},{"label":"B","text":"count++ is a single indivisible instruction on every CPU"},{"label":"C","text":"count++ always requires a system call"},{"label":"D","text":"count++ can only run in kernel mode"}],"ans":"A","explanation":"count++ compiles to load, add, store. If both threads load the same old value, both store old+1 and one increment is lost. This is a race condition."},{"q":"Which of the following is NOT a requirement of a correct solution to the critical-section problem?","opts":[{"label":"A","text":"Mutual exclusion"},{"label":"B","text":"Progress"},{"label":"C","text":"Bounded waiting"},{"label":"D","text":"All processes must run at the same speed"}],"ans":"D","explanation":"A solution must work without assuming anything about relative process speeds. The three requirements are mutual exclusion, progress and bounded waiting."},{"q":"A counting semaphore is initialised to 10. After 6 wait (P) and 4 signal (V) operations have completed, what is its value?","opts":[{"label":"A","text":"0"},{"label":"B","text":"8"},{"label":"C","text":"10"},{"label":"D","text":"12"}],"ans":"B","explanation":"Each wait decrements and each signal increments: 10 − 6 + 4 = 8."},{"q":"To use a semaphore for mutual exclusion around a critical section, its initial value should be:","opts":[{"label":"A","text":"1"},{"label":"B","text":"−1"},{"label":"C","text":"0"},{"label":"D","text":"N (the number of processes)"}],"ans":"A","explanation":"A binary semaphore initialised to 1 lets exactly one process in at a time. Initial value 0 would block everyone forever."},{"q":"For a bounded buffer of size N with semaphores mutex, empty and full, what are the correct initial values?","opts":[{"label":"A","text":"mutex = 1, empty = 0, full = N"},{"label":"B","text":"mutex = 1, empty = N, full = 0"},{"label":"C","text":"mutex = 1, empty = N, full = N"},{"label":"D","text":"mutex = 0, empty = N, full = 0"}],"ans":"B","explanation":"mutex = 1 (buffer free to use), empty = N (all slots empty initially), full = 0 (no items to consume yet)."},{"q":"In a bounded-buffer producer, wait(mutex) is mistakenly executed BEFORE wait(empty). The buffer is full. What happens?","opts":[{"label":"A","text":"The consumer starves but the system eventually recovers"},{"label":"B","text":"Deadlock: the producer holds mutex while waiting for an empty slot, so the consumer can never enter to free one"},{"label":"C","text":"The producer overwrites the oldest item"},{"label":"D","text":"Nothing, because mutex is a binary semaphore"}],"ans":"B","explanation":"The producer sleeps on empty while still holding mutex. The consumer needs mutex to remove an item, so neither can proceed. Always wait on empty/full first, then mutex."},{"q":"When is a spinlock preferable to a sleeping mutex?","opts":[{"label":"A","text":"When the lock is held across a disk I/O"},{"label":"B","text":"On a single-CPU system"},{"label":"C","text":"When the critical section is long"},{"label":"D","text":"When the critical section is extremely short and the system has multiple CPUs"}],"ans":"D","explanation":"Spinning wastes CPU, but if the lock will be released within a few instructions it is cheaper than the cost of two context switches to sleep and wake. On a single CPU, spinning is pointless because the lock holder cannot run."},{"q":"A simple spinlock built on the atomic test-and-set instruction guarantees mutual exclusion. Which property can still be violated?","opts":[{"label":"A","text":"Mutual exclusion"},{"label":"B","text":"Progress"},{"label":"C","text":"Bounded waiting"},{"label":"D","text":"Atomicity of the test-and-set itself"}],"ans":"C","explanation":"There is no queue, so an unlucky thread can keep losing the race every time the lock is released. Bounded waiting is not guaranteed."},{"q":"Which statement correctly distinguishes a mutex from a binary semaphore?","opts":[{"label":"A","text":"A mutex can take values from 0 to N"},{"label":"B","text":"A mutex must be released by the thread that locked it; a binary semaphore can be signalled by a different thread"},{"label":"C","text":"A binary semaphore has an owner; a mutex does not"},{"label":"D","text":"They are identical in every respect"}],"ans":"B","explanation":"A mutex has ownership. A binary semaphore is a signalling mechanism, so one thread can wait() and another can signal()."},{"q":"Three identical printers are guarded by a counting semaphore initialised to 3. Five processes call wait() at nearly the same time. How many get blocked?","opts":[{"label":"A","text":"0"},{"label":"B","text":"2"},{"label":"C","text":"3"},{"label":"D","text":"5"}],"ans":"B","explanation":"The first three wait() calls succeed and bring the value to 0. The remaining two block until some process calls signal()."},{"q":"Semaphores A = 1 and B = 1. P1 runs wait(A); wait(B); ... and P2 runs wait(B); wait(A); ... What can happen?","opts":[{"label":"A","text":"Mutual exclusion is violated"},{"label":"B","text":"Nothing, because both semaphores are binary"},{"label":"C","text":"Deadlock, if each process acquires its first semaphore before the other gets its second"},{"label":"D","text":"The OS kernel starves"}],"ans":"C","explanation":"P1 holds A and waits for B while P2 holds B and waits for A: a circular wait. The fix is to acquire locks in the same order in both processes."},{"q":"Which software-only solution satisfies mutual exclusion, progress and bounded waiting for two processes?","opts":[{"label":"A","text":"Busy-waiting on a shared integer with no other variables"},{"label":"B","text":"Peterson's solution (flag array plus turn variable)"},{"label":"C","text":"Strict alternation using only a turn variable"},{"label":"D","text":"A flag array only (each process sets its flag and waits for the other's flag to clear)"}],"ans":"B","explanation":"Strict alternation violates progress, flags-only can deadlock when both set their flags, and Peterson's solution (flag[] + turn) satisfies all three requirements."},{"q":"Five philosophers each pick up the left fork first and then the right one. If all do so at once, they deadlock. Which simple fix prevents this?","opts":[{"label":"A","text":"Increase the time quantum"},{"label":"B","text":"Give each philosopher a second left fork"},{"label":"C","text":"Allow at most four philosophers to sit at the table at the same time"},{"label":"D","text":"Let each philosopher hold forks for longer"}],"ans":"C","explanation":"With at most 4 seated, at least one philosopher can always obtain both forks, so a circular wait cannot form. Other fixes: asymmetric pick-up order, or picking up both forks atomically."},{"q":"In the first readers–writers solution (readers get priority), which problem can occur?","opts":[{"label":"A","text":"Mutual exclusion among readers is violated"},{"label":"B","text":"Writers may starve"},{"label":"C","text":"Readers starve"},{"label":"D","text":"Deadlock is guaranteed"}],"ans":"B","explanation":"As long as new readers keep arriving, a waiting writer never gets access, so writers can starve. Multiple readers are allowed together by design."},{"q":"A low-priority task holds a lock needed by a high-priority task, while a medium-priority task keeps preempting the low-priority one. This is priority inversion. What is the standard fix?","opts":[{"label":"A","text":"Delete the high-priority task"},{"label":"B","text":"Remove the lock"},{"label":"C","text":"Decrease the time quantum"},{"label":"D","text":"Priority inheritance: the lock holder temporarily runs at the waiter's priority"}],"ans":"D","explanation":"With priority inheritance the low-priority holder is boosted so it can finish the critical section and release the lock quickly."},{"q":"Which of the following is NOT a necessary condition for deadlock?","opts":[{"label":"A","text":"Circular wait"},{"label":"B","text":"Mutual exclusion"},{"label":"C","text":"Resource preemption"},{"label":"D","text":"Hold and wait"}],"ans":"C","explanation":"The Coffman conditions are mutual exclusion, hold and wait, NO preemption, and circular wait. Allowing preemption would break deadlock."},{"q":"Which technique prevents deadlock by breaking the circular-wait condition?","opts":[{"label":"A","text":"Requiring a process to request all its resources at the start"},{"label":"B","text":"Preempting resources from waiting processes"},{"label":"C","text":"Making every resource sharable"},{"label":"D","text":"Imposing a global ordering on resource types and requesting them only in increasing order"}],"ans":"D","explanation":"With a total order and increasing-order requests, a cycle of waiting processes cannot form. The first option breaks hold-and-wait, the second breaks no-preemption, the third breaks mutual exclusion."},{"q":"A system has 12 tape drives and 3 processes. Maximum need / currently held: P0 10/5, P1 4/2, P2 9/2. Is the state safe?","opts":[{"label":"A","text":"Safe, with safe sequence <P0, P1, P2>"},{"label":"B","text":"Unsafe, but not yet deadlocked"},{"label":"C","text":"Safe, with safe sequence <P1, P0, P2>"},{"label":"D","text":"Already deadlocked"}],"ans":"C","explanation":"Available = 12 − 9 = 3. P1 needs 2 more → runs, releases, available = 5. P0 needs 5 → runs, available = 10. P2 needs 7 → runs. <P0, …> fails first because P0 needs 5 but only 3 are free."},{"q":"4 processes each need a maximum of 3 instances of the same resource type. What is the minimum number of instances that makes deadlock impossible?","opts":[{"label":"A","text":"8"},{"label":"B","text":"9"},{"label":"C","text":"10"},{"label":"D","text":"12"}],"ans":"B","explanation":"Worst case every process holds (3 − 1) = 2 instances: 4 × 2 = 8 used and all stuck. One more instance (9) lets some process finish. Formula: n(k − 1) + 1 = 4 × 2 + 1 = 9."},{"q":"In a resource allocation graph where every resource type has a single instance, a cycle means:","opts":[{"label":"A","text":"Only starvation, never deadlock"},{"label":"B","text":"The system is in a safe state"},{"label":"C","text":"Possible deadlock, but not certain"},{"label":"D","text":"Definitely a deadlock"}],"ans":"D","explanation":"With single-instance resources, a cycle is both necessary and sufficient for deadlock. With multiple instances, a cycle only indicates a possible deadlock."},{"q":"Banker's algorithm with resource types A, B, C. Allocation: P0 (0,1,0), P1 (2,0,0), P2 (3,0,2), P3 (2,1,1), P4 (0,0,2). Max: P0 (7,5,3), P1 (3,2,2), P2 (9,0,2), P3 (2,2,2), P4 (4,3,3). Available = (3,3,2). What is the Need of P0?","opts":[{"label":"A","text":"(0,1,0)"},{"label":"B","text":"(3,3,2)"},{"label":"C","text":"(7,5,3)"},{"label":"D","text":"(7,4,3)"}],"ans":"D","explanation":"Need = Max − Allocation = (7,5,3) − (0,1,0) = (7,4,3)."},{"q":"Banker's algorithm with resource types A, B, C. Allocation: P0 (0,1,0), P1 (2,0,0), P2 (3,0,2), P3 (2,1,1), P4 (0,0,2). Max: P0 (7,5,3), P1 (3,2,2), P2 (9,0,2), P3 (2,2,2), P4 (4,3,3). Available = (3,3,2). Which of the following is a safe sequence?","opts":[{"label":"A","text":"<P2, P1, P3, P4, P0>"},{"label":"B","text":"<P1, P3, P4, P0, P2>"},{"label":"C","text":"<P4, P0, P1, P2, P3>"},{"label":"D","text":"<P0, P1, P2, P3, P4>"}],"ans":"B","explanation":"Needs: P0 (7,4,3), P1 (1,2,2), P2 (6,0,0), P3 (0,1,1), P4 (4,3,1). P1 fits in (3,3,2) → available (5,3,2); P3 fits → (7,4,3); P4 fits → (7,4,5); P0 fits → (7,5,5); P2 fits. The other sequences start with a process whose Need exceeds the Available vector."},{"q":"The Banker's algorithm is an example of:","opts":[{"label":"A","text":"Deadlock avoidance"},{"label":"B","text":"Deadlock prevention"},{"label":"C","text":"Deadlock recovery"},{"label":"D","text":"Deadlock detection"}],"ans":"A","explanation":"Banker's algorithm checks, before granting each request, whether the resulting state is safe. That is avoidance (it needs advance knowledge of maximum demands)."},{"q":"Which approach do general-purpose OSes such as Unix and Windows effectively take towards deadlocks among user programs (the 'ostrich' approach)?","opts":[{"label":"A","text":"Run the Banker's algorithm on every request"},{"label":"B","text":"Allow only one process at a time"},{"label":"C","text":"Reboot the machine every hour"},{"label":"D","text":"Ignore the problem and leave it to programmers, since deadlocks are rare and prevention is costly"}],"ans":"D","explanation":"Prevention and avoidance impose heavy restrictions or overhead, and deadlocks are rare, so most systems simply ignore them."},{"q":"3 processes each need at most 2 units of the same resource. What is the minimum number of units that guarantees deadlock-free execution?","opts":[{"label":"A","text":"6"},{"label":"B","text":"5"},{"label":"C","text":"4"},{"label":"D","text":"3"}],"ans":"C","explanation":"Use n(k − 1) + 1 = 3 × (2 − 1) + 1 = 4. With only 3 units, each process could hold one unit and wait for a second forever."},{"q":"A system uses 32-bit logical addresses and a page size of 4 KB. How many bits are used for the page number?","opts":[{"label":"A","text":"10"},{"label":"B","text":"12"},{"label":"C","text":"20"},{"label":"D","text":"22"}],"ans":"C","explanation":"4 KB = 2^12 bytes → 12 offset bits. Page number bits = 32 − 12 = 20."},{"q":"32-bit virtual addresses, 4 KB pages, 4-byte page table entries, single-level page table. What is the page table size per process?","opts":[{"label":"A","text":"1 MB"},{"label":"B","text":"4 MB"},{"label":"C","text":"16 MB"},{"label":"D","text":"4 KB"}],"ans":"B","explanation":"Number of pages = 2^32 / 2^12 = 2^20. Table size = 2^20 × 4 bytes = 4 MB."},{"q":"Page size is 1 KB. Logical address 2700 lies in page 2, and page 2 is stored in frame 5. What is the physical address?","opts":[{"label":"A","text":"2700"},{"label":"B","text":"5120"},{"label":"C","text":"5772"},{"label":"D","text":"7820"}],"ans":"C","explanation":"Page number = 2700 / 1024 = 2, offset = 2700 − 2048 = 652. Physical address = 5 × 1024 + 652 = 5772."},{"q":"Single-level paging with TLB hit ratio 80%, TLB lookup 10 ns and memory access 100 ns. What is the effective access time?","opts":[{"label":"A","text":"110 ns"},{"label":"B","text":"120 ns"},{"label":"C","text":"130 ns"},{"label":"D","text":"210 ns"}],"ans":"C","explanation":"Hit: 10 + 100 = 110 ns. Miss: 10 + 100 (page table) + 100 (data) = 210 ns. EAT = 0.8 × 110 + 0.2 × 210 = 88 + 42 = 130 ns."},{"q":"Paging completely eliminates which type of fragmentation?","opts":[{"label":"A","text":"Neither"},{"label":"B","text":"External fragmentation"},{"label":"C","text":"Both internal and external"},{"label":"D","text":"Internal fragmentation"}],"ans":"B","explanation":"Any free frame can hold any page, so there is no external fragmentation. The last page of a process may be partly empty, so internal fragmentation remains."},{"q":"Memory partitions in order: 100K, 500K, 200K, 300K, 600K. Processes arrive in order: 212K, 417K, 112K, 426K. Using First Fit, which process cannot be allocated?","opts":[{"label":"A","text":"212K"},{"label":"B","text":"417K"},{"label":"C","text":"112K"},{"label":"D","text":"426K"}],"ans":"D","explanation":"212K → 500K (288K left). 417K → 600K (183K left). 112K → the 288K hole (176K left). Holes are now 100K, 176K, 200K, 300K, 183K, so 426K does not fit. (Best Fit would place all four.)"},{"q":"In a segmented system, a process accesses (segment 2, offset 700) but segment 2 has a limit of 500. What happens?","opts":[{"label":"A","text":"The address is translated normally"},{"label":"B","text":"The address wraps around into the next segment"},{"label":"C","text":"The hardware traps to the OS with an addressing error (segmentation fault)"},{"label":"D","text":"A page fault is raised and the page is loaded from disk"}],"ans":"C","explanation":"The MMU compares the offset to the segment limit. An offset beyond the limit is illegal, so the hardware traps to the OS."},{"q":"32-bit addresses, 4 KB pages, 4-byte page-table entries, two-level paging where each page table fits exactly in one page. How many bits index the outer page table?","opts":[{"label":"A","text":"8"},{"label":"B","text":"10"},{"label":"C","text":"12"},{"label":"D","text":"20"}],"ans":"B","explanation":"Offset = 12 bits. A page holds 4096 / 4 = 1024 = 2^10 entries, so the inner index uses 10 bits. The outer index gets the rest: 32 − 12 − 10 = 10 bits."},{"q":"TLB hit ratio 98%, TLB lookup 20 ns, memory access 100 ns, single-level paging. What is the effective access time?","opts":[{"label":"A","text":"140 ns"},{"label":"B","text":"125 ns"},{"label":"C","text":"122 ns"},{"label":"D","text":"120 ns"}],"ans":"C","explanation":"Hit = 20 + 100 = 120 ns. Miss = 20 + 100 + 100 = 220 ns. EAT = 0.98 × 120 + 0.02 × 220 = 117.6 + 4.4 = 122 ns."},{"q":"The size of an inverted page table depends on:","opts":[{"label":"A","text":"The amount of physical memory (number of frames)"},{"label":"B","text":"The page-fault rate"},{"label":"C","text":"The size of the virtual address space"},{"label":"D","text":"The number of processes"}],"ans":"A","explanation":"An inverted page table has one entry per physical frame, so it scales with physical memory, not with virtual address space or number of processes."},{"q":"Partitions in order: 100K, 500K, 200K, 300K, 600K. Processes 212K, 417K, 112K, 426K are allocated in this order using Best Fit. Which partition receives the 112K process?","opts":[{"label":"A","text":"100K"},{"label":"B","text":"200K"},{"label":"C","text":"300K"},{"label":"D","text":"500K"}],"ans":"B","explanation":"212K → 300K (smallest hole that fits). 417K → 500K. The holes are now 100K, 83K, 200K, 88K, 600K, and the smallest one that fits 112K is 200K. 426K then goes to 600K, so all four processes are placed."},{"q":"Compaction can reduce external fragmentation only if:","opts":[{"label":"A","text":"Relocation is dynamic (addresses are bound at execution time)"},{"label":"B","text":"All processes are small"},{"label":"C","text":"Paging is used"},{"label":"D","text":"First Fit is used"}],"ans":"A","explanation":"Compaction moves processes in memory, so their addresses must be re-bindable at run time (via base/relocation registers)."},{"q":"A logical address space has 64 pages of 1024 words each, mapped onto a physical memory of 32 frames. How many bits are in the logical and physical addresses respectively?","opts":[{"label":"A","text":"16 and 15"},{"label":"B","text":"16 and 16"},{"label":"C","text":"15 and 16"},{"label":"D","text":"10 and 5"}],"ans":"A","explanation":"Logical: 64 pages = 2^6 and page size 2^10 → 6 + 10 = 16 bits. Physical: 32 frames = 2^5 → 5 + 10 = 15 bits."},{"q":"A process is 72,766 bytes and the page size is 2,048 bytes. How much internal fragmentation occurs?","opts":[{"label":"A","text":"2,048 bytes"},{"label":"B","text":"1,086 bytes"},{"label":"C","text":"962 bytes"},{"label":"D","text":"0 bytes"}],"ans":"C","explanation":"72,766 / 2,048 ≈ 35.53, so 36 pages are needed = 73,728 bytes. Waste = 73,728 − 72,766 = 962 bytes, all in the last page."},{"q":"Which page replacement algorithm requires knowledge of future references and therefore cannot be implemented in practice?","opts":[{"label":"A","text":"FIFO"},{"label":"B","text":"Clock"},{"label":"C","text":"Optimal"},{"label":"D","text":"LRU"}],"ans":"C","explanation":"Optimal replaces the page that will not be used for the longest time. It is used only as a benchmark to compare other algorithms."},{"q":"Reference string: 7,0,1,2,0,3,0,4,2,3,0,3,2,1,2,0,1,7,0,1 with 3 frames. How many page faults does FIFO produce?","opts":[{"label":"A","text":"12"},{"label":"B","text":"15"},{"label":"C","text":"9"},{"label":"D","text":"18"}],"ans":"B","explanation":"Trace of frames after each fault: 7 | 7,0 | 7,0,1 | 2,0,1 | 2,3,1 | 2,3,0 | 4,3,0 | 4,2,0 | 4,2,3 | 0,2,3 | 0,1,3 | 0,1,2 | 7,1,2 | 7,0,2 | 7,0,1 = 15 faults."},{"q":"Same reference string and 3 frames: 7,0,1,2,0,3,0,4,2,3,0,3,2,1,2,0,1,7,0,1. How many page faults does LRU produce?","opts":[{"label":"A","text":"12"},{"label":"B","text":"15"},{"label":"C","text":"9"},{"label":"D","text":"10"}],"ans":"A","explanation":"LRU gives 12 faults (FIFO gives 15, Optimal gives 9). LRU uses the recent past as an approximation of the future."},{"q":"Belady's anomaly (more frames leading to more page faults) can occur with:","opts":[{"label":"A","text":"LRU"},{"label":"B","text":"Every page replacement algorithm"},{"label":"C","text":"Optimal"},{"label":"D","text":"FIFO"}],"ans":"D","explanation":"FIFO is not a stack algorithm, so it can show Belady's anomaly. LRU and Optimal are stack algorithms and never do."},{"q":"Memory access time is 200 ns, page-fault service time is 8 ms, and 1 in 1000 memory accesses causes a page fault. What is the effective access time?","opts":[{"label":"A","text":"about 200 ns"},{"label":"B","text":"about 800 ns"},{"label":"C","text":"about 2,000 ns"},{"label":"D","text":"about 8,200 ns"}],"ans":"D","explanation":"EAT = 0.999 × 200 + 0.001 × 8,000,000 ns = 199.8 + 8000 ≈ 8,200 ns. A tiny fault rate slows memory down about 40×."},{"q":"CPU utilisation drops sharply as the OS admits more processes, and the disk is constantly busy paging. What is the best remedy?","opts":[{"label":"A","text":"Increase the degree of multiprogramming"},{"label":"B","text":"Increase the time quantum"},{"label":"C","text":"Decrease the degree of multiprogramming (suspend some processes)"},{"label":"D","text":"Switch to FCFS scheduling"}],"ans":"C","explanation":"This is thrashing: processes do not have enough frames for their working sets, so they spend more time paging than executing. Reduce the number of active processes."},{"q":"Reference string: 1,2,3,4,1,2,5,1,2,3,4,5. How many page faults occur with FIFO and 3 frames?","opts":[{"label":"A","text":"7"},{"label":"B","text":"8"},{"label":"C","text":"9"},{"label":"D","text":"10"}],"ans":"C","explanation":"Faults on 1,2,3,4,1,2,5 (7 faults; the next 1 and 2 hit), then 3 and 4 fault; the final 5 hits. Total = 9."},{"q":"Reference string: 1,2,3,4,1,2,5,1,2,3,4,5. How many page faults occur with FIFO and 4 frames?","opts":[{"label":"A","text":"12"},{"label":"B","text":"10"},{"label":"C","text":"9"},{"label":"D","text":"8"}],"ans":"B","explanation":"With 4 frames: 1,2,3,4 fault, then 1 and 2 hit, and then 5,1,2,3,4,5 all fault = 10 faults. That is more than the 9 faults with 3 frames: Belady's anomaly."},{"q":"Reference string: 1,2,3,4,1,2,5,1,2,3,4,5. How many page faults occur with the Optimal algorithm and 3 frames?","opts":[{"label":"A","text":"6"},{"label":"B","text":"7"},{"label":"C","text":"8"},{"label":"D","text":"9"}],"ans":"B","explanation":"Optimal gives 7 faults. It evicts the page whose next use is furthest in the future (or never), e.g. 3 when 4 arrives, then 4 when 5 arrives."},{"q":"Reference string: 1,2,3,4,1,2,5,1,2,3,4,5. How many page faults occur with LRU and 3 frames?","opts":[{"label":"A","text":"8"},{"label":"B","text":"9"},{"label":"C","text":"10"},{"label":"D","text":"12"}],"ans":"C","explanation":"LRU gives 10 faults here (FIFO gave 9). LRU is not better on every string, but unlike FIFO it never suffers from Belady's anomaly."},{"q":"Memory access takes 100 ns and a page-fault service takes 10 ms. To keep the slowdown within 10% (EAT ≤ 110 ns), the page-fault rate must be below about:","opts":[{"label":"A","text":"1 in 1,000,000"},{"label":"B","text":"1 in 100,000"},{"label":"C","text":"1 in 10,000"},{"label":"D","text":"1 in 1,000"}],"ans":"A","explanation":"EAT = (1 − p) × 100 + p × 10,000,000 ≈ 100 + 9,999,900 × p. For EAT ≤ 110 ns we need p ≤ 10 / 9,999,900 ≈ 10^−6, i.e. about 1 fault per million accesses."},{"q":"During page replacement, why does the OS prefer a victim page whose dirty (modified) bit is 0?","opts":[{"label":"A","text":"It belongs to the kernel"},{"label":"B","text":"It need not be written back to disk, so the page fault is serviced faster"},{"label":"C","text":"It is the oldest page in memory"},{"label":"D","text":"It is guaranteed never to be used again"}],"ans":"B","explanation":"A clean page is identical to its copy on disk, so it can simply be overwritten, saving one disk write per fault."},{"q":"In the working-set model, what happens if the window size Δ is chosen too small?","opts":[{"label":"A","text":"It spans several localities and wastes memory"},{"label":"B","text":"Thrashing becomes impossible"},{"label":"C","text":"It does not cover the process's whole current locality, causing extra page faults"},{"label":"D","text":"The TLB is disabled"}],"ans":"C","explanation":"Too small a Δ misses part of the current locality; too large a Δ spans several localities and wastes frames. Total working-set demand above available frames signals thrashing."},{"q":"Which of the following is NOT stored in a file's inode in a Unix-like file system?","opts":[{"label":"A","text":"File name"},{"label":"B","text":"Owner and permissions"},{"label":"C","text":"File size"},{"label":"D","text":"Pointers to data blocks"}],"ans":"A","explanation":"The file name lives in the directory entry, which maps a name to an inode number. The inode holds everything else about the file."},{"q":"Which file allocation method needs to follow n pointers to reach the nth block, making random access slow?","opts":[{"label":"A","text":"Contiguous allocation"},{"label":"B","text":"Linked allocation"},{"label":"C","text":"Indexed allocation"},{"label":"D","text":"None of these"}],"ans":"B","explanation":"In linked allocation each block points to the next, so direct access to block n means n pointer hops. Contiguous and indexed allocation support direct access."},{"q":"Disk head is at cylinder 53. Request queue: 98, 183, 37, 122, 14, 124, 65, 67. What is the total head movement with SSTF?","opts":[{"label":"A","text":"640"},{"label":"B","text":"299"},{"label":"C","text":"208"},{"label":"D","text":"236"}],"ans":"D","explanation":"Order: 53→65 (12), →67 (2), →37 (30), →14 (23), →98 (84), →122 (24), →124 (2), →183 (59). Total = 236. (FCFS would be 640.)"},{"q":"Which disk scheduling algorithm gives a more uniform wait time than SCAN by treating the cylinders as a circular list?","opts":[{"label":"A","text":"C-SCAN"},{"label":"B","text":"LOOK"},{"label":"C","text":"FCFS"},{"label":"D","text":"SSTF"}],"ans":"A","explanation":"C-SCAN services requests in one direction only, then jumps back to the start without servicing on the return trip, so edge cylinders are not favoured less than middle ones."},{"q":"What is the main advantage of DMA over interrupt-driven programmed I/O for bulk transfers?","opts":[{"label":"A","text":"No main memory is needed"},{"label":"B","text":"Device drivers are no longer required"},{"label":"C","text":"The CPU is interrupted once per block transferred instead of once per byte or word"},{"label":"D","text":"The device itself becomes faster"}],"ans":"C","explanation":"The DMA controller moves data between the device and memory on its own and interrupts the CPU only when the whole transfer is complete."},{"q":"A disk rotates at 7200 RPM. What is the average rotational latency?","opts":[{"label":"A","text":"2.08 ms"},{"label":"B","text":"4.17 ms"},{"label":"C","text":"8.33 ms"},{"label":"D","text":"16.67 ms"}],"ans":"B","explanation":"One rotation = 60 / 7200 s = 8.33 ms. On average the sector is half a rotation away: 8.33 / 2 = 4.17 ms."},{"q":"Disk head at cylinder 50 on a disk with cylinders 0–199. Request queue: 82, 170, 43, 140, 24, 16, 190. What is the total head movement under FCFS?","opts":[{"label":"A","text":"208"},{"label":"B","text":"565"},{"label":"C","text":"642"},{"label":"D","text":"700"}],"ans":"C","explanation":"50→82 (32), →170 (88), →43 (127), →140 (97), →24 (116), →16 (8), →190 (174). Total = 642."},{"q":"Disk head at cylinder 50 on a disk with cylinders 0–199. Request queue: 82, 170, 43, 140, 24, 16, 190. What is the total head movement under SSTF?","opts":[{"label":"A","text":"208"},{"label":"B","text":"314"},{"label":"C","text":"332"},{"label":"D","text":"642"}],"ans":"A","explanation":"Order: 50→43 (7), →24 (19), →16 (8), →82 (66), →140 (58), →170 (30), →190 (20). Total = 208."},{"q":"Disk head at cylinder 50 on a disk with cylinders 0–199. Request queue: 82, 170, 43, 140, 24, 16, 190. The head is moving towards higher cylinders. What is the total head movement under SCAN?","opts":[{"label":"A","text":"314"},{"label":"B","text":"332"},{"label":"C","text":"349"},{"label":"D","text":"642"}],"ans":"B","explanation":"SCAN goes to the end of the disk: 50→199 (149), then reverses down to 16 (183). Total = 332. (LOOK, which reverses at the last request 190 instead, would give 140 + 174 = 314.)"},{"q":"A file has one hard link and one soft (symbolic) link pointing to it. The original file name is then deleted. What happens?","opts":[{"label":"A","text":"Both links stop working immediately"},{"label":"B","text":"The hard link still works; the soft link becomes dangling"},{"label":"C","text":"Both links still work"},{"label":"D","text":"The soft link still works; the hard link becomes dangling"}],"ans":"B","explanation":"A hard link is another directory entry for the same inode, so the data survives until the link count reaches 0. A soft link just stores a path, which no longer resolves."},{"q":"An inode has 12 direct pointers and 1 single-indirect pointer. Block size is 4 KB and each pointer is 4 bytes. What is the maximum file size?","opts":[{"label":"A","text":"48 KB"},{"label":"B","text":"4 MB"},{"label":"C","text":"4144 KB (4 MB + 48 KB)"},{"label":"D","text":"4 GB"}],"ans":"C","explanation":"Direct: 12 × 4 KB = 48 KB. Single indirect: 4 KB / 4 B = 1024 pointers × 4 KB = 4096 KB. Total = 4144 KB."},{"q":"Which technique lets many processes 'print' at once by writing to a queue on disk that the printer drains later?","opts":[{"label":"A","text":"Swapping"},{"label":"B","text":"Paging"},{"label":"C","text":"Thrashing"},{"label":"D","text":"Spooling"}],"ans":"D","explanation":"Spooling (Simultaneous Peripheral Operations On-Line) buffers output for a slow, non-shareable device such as a printer, so processes don't have to wait for it."},{"q":"Each process believes it has a private, contiguous address space starting at 0. Which of the OS's three jobs is this?","opts":[{"label":"A","text":"Illusionist"},{"label":"B","text":"Referee"},{"label":"C","text":"Glue"},{"label":"D","text":"Bootloader"}],"ans":"A","explanation":"Virtual memory is the OS lying to each process (illusionist). Protecting processes from each other is the referee job; hiding disk blocks behind files is the glue job."},{"q":"Which statement about starvation and deadlock is correct?","opts":[{"label":"A","text":"Starvation and deadlock are the same thing"},{"label":"B","text":"Deadlock cannot occur when semaphores are used"},{"label":"C","text":"Deadlocked processes starve, but starvation can also occur without any deadlock"},{"label":"D","text":"Starvation always implies deadlock"}],"ans":"C","explanation":"Deadlocked processes wait forever, so they do starve. But a process can also starve in a healthy system (e.g. a low-priority process under SJF or priority scheduling), with no deadlock at all."}]},{"id":"bank-computer-networks-placement","name":"Computer Networks — Placement MCQs","icon":"⌁","description":"75 placement-focused questions on OSI, TCP/UDP, IP, DNS, HTTP, routing and network security","questions":[{"id":"cn-001","q":"How many layers are in the OSI reference model?","opts":["A. 4","B. 5","C. 7","D. 8"],"ans":"C","explanation":"The OSI model has seven layers, from Physical to Application."},{"id":"cn-002","q":"Which is the correct OSI layer order from bottom to top?","opts":["A. Physical, Data Link, Network, Transport, Session, Presentation, Application","B. Application, Presentation, Session, Network, Transport, Data Link, Physical","C. Physical, Network, Data Link, Session, Transport, Application, Presentation","D. Data Link, Physical, Network, Transport, Presentation, Session, Application"],"ans":"A","explanation":"The standard bottom-to-top order is Physical, Data Link, Network, Transport, Session, Presentation, Application."},{"id":"cn-003","q":"At which OSI layer does TCP operate?","opts":["A. Network","B. Transport","C. Session","D. Data Link"],"ans":"B","explanation":"TCP provides end-to-end transport services and is associated with Layer 4."},{"id":"cn-004","q":"At which OSI layer does IP primarily operate?","opts":["A. Physical","B. Data Link","C. Network","D. Application"],"ans":"C","explanation":"IP addressing and routing between networks are Layer 3 functions."},{"id":"cn-005","q":"Which OSI layer is most associated with MAC addresses and Ethernet frames?","opts":["A. Data Link","B. Transport","C. Presentation","D. Session"],"ans":"A","explanation":"The Data Link layer handles local-link framing and MAC addressing."},{"id":"cn-006","q":"Which OSI layer transmits raw bits over a medium?","opts":["A. Application","B. Network","C. Physical","D. Transport"],"ans":"C","explanation":"The Physical layer sends signals and bits over a physical or radio medium."},{"id":"cn-007","q":"Which TCP/IP layer groups the OSI Session, Presentation and Application layers?","opts":["A. Internet","B. Transport","C. Link","D. Application"],"ans":"D","explanation":"The TCP/IP model's Application layer covers the upper OSI layers."},{"id":"cn-008","q":"Which statement best describes encapsulation?","opts":["A. Removing all headers at the sender","B. Each layer adds its own control information around data","C. Encrypting every packet automatically","D. Converting IP addresses to domain names"],"ans":"B","explanation":"As data moves down the stack, layers add headers and sometimes trailers."},{"id":"cn-009","q":"What is the usual protocol data unit at the Data Link layer?","opts":["A. Segment","B. Packet","C. Frame","D. Bit"],"ans":"C","explanation":"The Data Link layer packages data into frames."},{"id":"cn-010","q":"Which device primarily forwards Ethernet frames using a MAC address table?","opts":["A. Router","B. Layer-2 switch","C. Repeater","D. DNS resolver"],"ans":"B","explanation":"A Layer-2 switch learns MAC addresses and forwards frames within a LAN."},{"id":"cn-011","q":"Which device forwards IP packets between different networks?","opts":["A. Hub","B. Layer-2 bridge only","C. Router","D. Repeater"],"ans":"C","explanation":"Routers use network-layer addressing and routing tables to forward packets."},{"id":"cn-012","q":"What is the main behavior of a traditional Ethernet hub?","opts":["A. Learns destination MAC addresses","B. Routes by IP prefix","C. Repeats incoming bits to all other ports","D. Assigns IP addresses using DHCP"],"ans":"C","explanation":"A hub operates at the physical layer and repeats signals to other ports."},{"id":"cn-013","q":"What does ARP resolve in a typical IPv4 LAN?","opts":["A. Domain name to public IP","B. IPv4 address to a local-link MAC address","C. Port number to process ID","D. MAC address to TCP port"],"ans":"B","explanation":"ARP discovers the link-layer address associated with a known IPv4 address on the local link."},{"id":"cn-014","q":"A host wants to send to an IP address outside its subnet. Which MAC address does it usually target in the first Ethernet frame?","opts":["A. The remote server's MAC address","B. The DNS server's MAC address in all cases","C. The default gateway's MAC address","D. A broadcast MAC in every case"],"ans":"C","explanation":"The host sends the frame to its next hop, normally the default gateway."},{"id":"cn-015","q":"What is the purpose of a subnet mask or prefix length?","opts":["A. To encrypt packets","B. To distinguish network bits from host bits in an IP address","C. To choose a TCP port","D. To map a domain to a URL"],"ans":"B","explanation":"A subnet prefix identifies which bits represent the network portion."},{"id":"cn-016","q":"How many total IPv4 addresses are in a /24 subnet?","opts":["A. 24","B. 128","C. 254","D. 256"],"ans":"D","explanation":"A /24 leaves 8 host bits, so it contains 2^8 = 256 addresses."},{"id":"cn-017","q":"How many commonly usable host addresses are in a conventional IPv4 /26 subnet?","opts":["A. 30","B. 62","C. 64","D. 126"],"ans":"B","explanation":"A /26 leaves 6 host bits: 64 total addresses, typically 62 usable after network and broadcast addresses."},{"id":"cn-018","q":"Which IPv4 address is a loopback address?","opts":["A. 8.8.8.8","B. 192.168.1.1","C. 127.0.0.1","D. 169.254.1.1"],"ans":"C","explanation":"127.0.0.1 is the commonly used IPv4 loopback address."},{"id":"cn-019","q":"Which range is private IPv4 address space?","opts":["A. 11.0.0.0/8","B. 172.16.0.0/12","C. 100.0.0.0/8","D. 200.0.0.0/8"],"ans":"B","explanation":"172.16.0.0 through 172.31.255.255 is reserved for private networks."},{"id":"cn-020","q":"What is the primary purpose of NAT in many home routers?","opts":["A. Convert TCP to UDP","B. Translate addresses, often allowing private hosts to share a public IPv4 address","C. Replace DNS","D. Prevent all malware"],"ans":"B","explanation":"Network Address Translation rewrites address information between network realms; home routers often use port translation too."},{"id":"cn-021","q":"Which protocol automatically leases IP configuration to clients?","opts":["A. DNS","B. DHCP","C. ARP","D. SMTP"],"ans":"B","explanation":"DHCP can provide an IP address, subnet mask, default gateway and DNS servers."},{"id":"cn-022","q":"What is the common order of the DHCPv4 DORA exchange?","opts":["A. Discover, Offer, Request, Acknowledge","B. Request, Discover, Acknowledge, Offer","C. Offer, Discover, Request, Acknowledge","D. Discover, Request, Offer, Acknowledge"],"ans":"A","explanation":"DORA stands for Discover, Offer, Request and Acknowledge."},{"id":"cn-023","q":"What does DNS primarily do?","opts":["A. Assign MAC addresses","B. Resolve domain names to records such as IP addresses","C. Encrypt all application traffic","D. Guarantee packet delivery"],"ans":"B","explanation":"DNS maps names to records, including A and AAAA address records."},{"id":"cn-024","q":"Which port is the default well-known port for DNS queries?","opts":["A. 25","B. 53","C. 80","D. 443"],"ans":"B","explanation":"DNS commonly uses port 53 over UDP or TCP, depending on the operation and response."},{"id":"cn-025","q":"Which record type maps a hostname to an IPv4 address?","opts":["A. AAAA","B. MX","C. A","D. CNAME only"],"ans":"C","explanation":"An A record contains an IPv4 address; AAAA is for IPv6."},{"id":"cn-026","q":"Which protocol commonly uses TCP port 443 for secure web traffic?","opts":["A. HTTPS","B. DHCP","C. TFTP","D. SNMP"],"ans":"A","explanation":"HTTPS conventionally uses TCP port 443, though HTTP/3 uses QUIC over UDP."},{"id":"cn-027","q":"Which default port is associated with HTTP over TCP?","opts":["A. 21","B. 22","C. 80","D. 110"],"ans":"C","explanation":"TCP port 80 is the conventional default for HTTP."},{"id":"cn-028","q":"Which protocol is commonly used to send email between mail servers?","opts":["A. SMTP","B. FTP","C. ARP","D. ICMP"],"ans":"A","explanation":"SMTP is used for sending and relaying email."},{"id":"cn-029","q":"Which protocol is used to transfer files and traditionally uses TCP ports 20/21?","opts":["A. DNS","B. FTP","C. DHCP","D. ICMP"],"ans":"B","explanation":"FTP uses separate control and data connections in its traditional modes."},{"id":"cn-030","q":"Which protocol is commonly used for secure remote shell access on port 22?","opts":["A. Telnet","B. SSH","C. SMTP","D. SNMP"],"ans":"B","explanation":"SSH provides encrypted remote login and command execution."},{"id":"cn-031","q":"Which transport protocol is connection-oriented and provides ordered reliable byte-stream delivery?","opts":["A. UDP","B. IP","C. TCP","D. ARP"],"ans":"C","explanation":"TCP uses sequence numbers, acknowledgments and retransmissions to provide reliable ordered delivery."},{"id":"cn-032","q":"Which is a key characteristic of UDP?","opts":["A. It guarantees in-order delivery","B. It requires a three-way handshake","C. It is connectionless and does not guarantee delivery","D. It retransmits every lost datagram automatically"],"ans":"C","explanation":"UDP has low overhead but leaves reliability and ordering to the application if needed."},{"id":"cn-033","q":"Which application is a common example where UDP can be useful because low latency matters?","opts":["A. Real-time voice/video","B. A file transfer requiring every byte in order without app-level recovery","C. A database transaction that relies only on UDP","D. A traditional SSH session"],"ans":"A","explanation":"Real-time media can prefer timely delivery over retransmitting late packets."},{"id":"cn-034","q":"What are the three messages in the TCP connection handshake?","opts":["A. ACK, FIN, ACK","B. SYN, SYN-ACK, ACK","C. SYN, ACK, FIN","D. HELLO, OFFER, REQUEST"],"ans":"B","explanation":"The three-way handshake synchronizes initial sequence numbers in both directions."},{"id":"cn-035","q":"What is the main purpose of TCP sequence numbers?","opts":["A. Identify DNS servers","B. Track byte positions to support ordering and loss recovery","C. Select the Wi-Fi channel","D. Encrypt the payload"],"ans":"B","explanation":"Sequence numbers identify positions in the byte stream, enabling ordering and retransmission."},{"id":"cn-036","q":"What does a TCP ACK generally communicate?","opts":["A. The receiver acknowledges data received up to a byte position","B. The sender has changed its IP address","C. The connection is always encrypted","D. The router has resolved DNS"],"ans":"A","explanation":"TCP acknowledgments confirm received sequence-space data, often cumulatively."},{"id":"cn-037","q":"What is TCP flow control designed to protect?","opts":["A. The receiver from being overwhelmed by the sender","B. The network from all congestion","C. The DNS cache from stale records","D. The link-layer switch from loops"],"ans":"A","explanation":"The advertised receive window helps limit data to what the receiver can buffer."},{"id":"cn-038","q":"What is TCP congestion control designed to respond to?","opts":["A. A missing domain name","B. Network congestion and the risk of overloading the path","C. A mismatch between MAC and IP formats only","D. A low battery on the receiver"],"ans":"B","explanation":"Congestion control adjusts sending behavior based on signs of network congestion."},{"id":"cn-039","q":"Which statement correctly distinguishes flow control from congestion control?","opts":["A. They are identical mechanisms","B. Flow control protects the receiver; congestion control protects the network path","C. Flow control is only for UDP","D. Congestion control assigns IP addresses"],"ans":"B","explanation":"They address different bottlenecks: receiver capacity versus network capacity."},{"id":"cn-040","q":"Which TCP flag is commonly used to initiate connection termination?","opts":["A. SYN","B. PSH","C. FIN","D. URG"],"ans":"C","explanation":"FIN indicates that a sender has finished sending data in that direction."},{"id":"cn-041","q":"Why can UDP be suitable for DNS queries?","opts":["A. DNS never needs responses","B. A simple query-response exchange can use low-overhead datagrams, with retries handled when needed","C. UDP guarantees delivery","D. UDP encrypts DNS by default"],"ans":"B","explanation":"Traditional DNS often uses UDP for ordinary queries; clients can retry and TCP is also used when required."},{"id":"cn-042","q":"Which protocol reports network-layer errors and diagnostic information, such as echo requests?","opts":["A. ICMP","B. FTP","C. SMTP","D. DHCP"],"ans":"A","explanation":"ICMP carries control and diagnostic messages; ping commonly uses ICMP echo messages."},{"id":"cn-043","q":"What does ping primarily use to test reachability?","opts":["A. TCP SYN to port 80 only","B. ICMP Echo Request and Echo Reply","C. ARP requests across the entire internet","D. DNS MX records"],"ans":"B","explanation":"Ping commonly sends ICMP echo requests and checks for echo replies."},{"id":"cn-044","q":"What is the purpose of a default gateway?","opts":["A. Resolve every hostname","B. Forward traffic destined for networks outside the local subnet","C. Store browser cookies","D. Assign a process a port number"],"ans":"B","explanation":"The default gateway is the next hop for destinations without a more specific route."},{"id":"cn-045","q":"What does a routing table help a router determine?","opts":["A. Which route or next hop to use for a destination prefix","B. Which HTML tag to render","C. Which user password is valid","D. How to compress every file"],"ans":"A","explanation":"Routers select a matching route, typically using longest-prefix matching."},{"id":"cn-046","q":"What is the main purpose of a firewall?","opts":["A. Automatically increase bandwidth","B. Apply rules to allow or block network traffic","C. Replace all routing protocols","D. Convert hostnames to MAC addresses"],"ans":"B","explanation":"Firewalls enforce traffic policies based on configured criteria."},{"id":"cn-047","q":"What does a VPN commonly provide?","opts":["A. A private or protected tunnel across an untrusted network","B. Guaranteed anonymity from every website","C. A replacement for all IP addresses","D. Automatic elimination of phishing"],"ans":"A","explanation":"VPNs commonly tunnel traffic and may encrypt it between endpoints."},{"id":"cn-048","q":"What is the main role of TLS in HTTPS?","opts":["A. Assign an IP address","B. Provide encryption, integrity and authenticated server identity when correctly validated","C. Route packets between subnets","D. Replace TCP sequence numbers"],"ans":"B","explanation":"TLS protects application data in transit and uses certificates to authenticate the server in typical HTTPS."},{"id":"cn-049","q":"What does a digital certificate help a browser verify in HTTPS?","opts":["A. That a website is always harmless","B. A public key is associated with the claimed identity, subject to certificate validation","C. That the server has unlimited bandwidth","D. That DNS cannot be spoofed"],"ans":"B","explanation":"Certificate-chain and hostname validation help bind a public key to the site's identity."},{"id":"cn-050","q":"Which HTTP method is intended to retrieve a representation of a resource?","opts":["A. GET","B. DELETE","C. CONNECT only","D. TRACE only"],"ans":"A","explanation":"GET requests a resource representation and is defined as a safe method."},{"id":"cn-051","q":"Which HTTP status code means 'Not Found'?","opts":["A. 200","B. 301","C. 404","D. 503"],"ans":"C","explanation":"404 indicates the server did not find a current representation for the target resource."},{"id":"cn-052","q":"What does HTTP status code 500 indicate?","opts":["A. Successful response","B. Internal server error","C. Permanent redirect","D. Client authentication succeeded"],"ans":"B","explanation":"500 is a generic server-side error response."},{"id":"cn-053","q":"What is the primary difference between HTTP and HTTPS?","opts":["A. HTTPS uses HTTP over TLS for protected transport","B. HTTP always uses UDP and HTTPS always uses TCP","C. HTTPS does not use URLs","D. HTTP supports images but HTTPS does not"],"ans":"A","explanation":"HTTPS secures HTTP traffic with TLS; HTTP alone does not provide TLS protection."},{"id":"cn-054","q":"What is the main advantage of HTTP/2 over HTTP/1.1?","opts":["A. It removes headers entirely","B. It supports multiplexing multiple streams over one connection","C. It only works without encryption","D. It replaces DNS"],"ans":"B","explanation":"HTTP/2 multiplexes streams on a connection and compresses headers."},{"id":"cn-055","q":"HTTP/3 is based on which transport protocol?","opts":["A. TCP directly","B. QUIC over UDP","C. ICMP","D. ARP"],"ans":"B","explanation":"HTTP/3 uses QUIC, which runs over UDP and provides transport features including encryption integration."},{"id":"cn-056","q":"What happens first in a typical browser visit to a new domain, if the address is not already cached?","opts":["A. The browser sends the HTML before resolving the server","B. The system performs DNS resolution to find an address","C. The router creates the website","D. The server sends a TCP ACK before any packet arrives"],"ans":"B","explanation":"The client usually resolves the hostname before connecting to the destination IP."},{"id":"cn-057","q":"After DNS resolution, what typically happens before an HTTPS request over HTTP/1.1 or HTTP/2 is sent over TCP?","opts":["A. TCP connection establishment and TLS handshake","B. DHCP DORA every time","C. ARP resolution across the entire internet","D. A new MAC address is assigned to the website"],"ans":"A","explanation":"A TCP connection is established, then TLS negotiates a protected session before HTTP data is exchanged."},{"id":"cn-058","q":"What is a socket commonly identified by in a TCP connection?","opts":["A. Only the browser window title","B. Protocol plus local and remote IP addresses and port numbers","C. Only the destination MAC address","D. Only the DNS record type"],"ans":"B","explanation":"A TCP connection is distinguished by endpoint address/port pairs and the transport protocol."},{"id":"cn-059","q":"What is a port number used for at the transport layer?","opts":["A. Identify an application endpoint on a host","B. Identify a physical cable","C. Replace the destination IP address","D. Specify the OSI layer count"],"ans":"A","explanation":"Ports help multiplex transport traffic to the appropriate application or service."},{"id":"cn-060","q":"Which port is commonly used by SSH by default?","opts":["A. 22","B. 53","C. 110","D. 143"],"ans":"A","explanation":"SSH's default well-known TCP port is 22."},{"id":"cn-061","q":"Which port is commonly used by SMTP for server-to-server mail relay without implicit TLS?","opts":["A. 25","B. 53","C. 123","D. 3389"],"ans":"A","explanation":"TCP port 25 is the conventional SMTP relay port."},{"id":"cn-062","q":"What is bandwidth?","opts":["A. The delay for one packet to arrive","B. The maximum data-carrying capacity of a link over time","C. The number of routers in a path","D. The number of bytes lost in one packet"],"ans":"B","explanation":"Bandwidth describes a link's capacity, often measured in bits per second."},{"id":"cn-063","q":"What is latency?","opts":["A. The time taken for data to travel from source to destination or for a response","B. The maximum capacity of a link","C. The total number of IP addresses","D. The size of a subnet"],"ans":"A","explanation":"Latency measures delay; round-trip time measures a trip to the destination and back."},{"id":"cn-064","q":"What is packet loss?","opts":["A. Packets arrive twice in every case","B. Some packets fail to reach the intended destination","C. A host receives a new IP address","D. A DNS record expires"],"ans":"B","explanation":"Packet loss means transmitted packets are dropped or otherwise fail to arrive."},{"id":"cn-065","q":"Which technique divides one physical switched network into separate logical Layer-2 broadcast domains?","opts":["A. VLAN","B. NAT only","C. DNS caching","D. TCP slow start"],"ans":"A","explanation":"VLANs logically segment a switched network into separate Layer-2 domains."},{"id":"cn-066","q":"What is the main purpose of Spanning Tree Protocol (STP) in Ethernet switching?","opts":["A. Prevent Layer-2 switching loops by blocking redundant paths when needed","B. Assign public IP addresses","C. Encrypt Wi-Fi traffic","D. Speed up DNS queries"],"ans":"A","explanation":"STP creates a loop-free logical topology while retaining redundant physical links."},{"id":"cn-067","q":"What does a proxy server commonly do?","opts":["A. Acts as an intermediary for requests between clients and other servers","B. Replace the physical layer","C. Guarantee a website is secure","D. Assign MAC addresses to routers"],"ans":"A","explanation":"A proxy receives and forwards requests, potentially applying caching, filtering or access controls."},{"id":"cn-068","q":"What is a CDN mainly used for?","opts":["A. Deliver content from distributed servers closer to users","B. Replace TCP with ARP","C. Assign a unique MAC address to every website","D. Prevent all DDoS attacks with certainty"],"ans":"A","explanation":"A content delivery network caches or serves content from geographically distributed edge locations."},{"id":"cn-069","q":"Which is the strongest general description of a DDoS attack?","opts":["A. One client requests its own home page","B. Many systems overwhelm a target with traffic or requests","C. A router updates its route table","D. A DNS lookup returns an IPv6 address"],"ans":"B","explanation":"Distributed denial of service uses multiple sources to exhaust a service or network resource."},{"id":"cn-070","q":"Which address type does IPv6 use?","opts":["A. 32-bit addresses only","B. 64-bit addresses only","C. 128-bit addresses","D. 16-bit addresses"],"ans":"C","explanation":"IPv6 addresses are 128 bits long."},{"id":"cn-071","q":"Which IPv6 address is the loopback address?","opts":["A. ::1","B. ::","C. fe80::1 only","D. ffff::1"],"ans":"A","explanation":"The IPv6 loopback address is ::1."},{"id":"cn-072","q":"Which statement about a MAC address is generally correct for Ethernet?","opts":["A. It is the normal Layer-2 address used for delivery on a local link","B. It is the same as a domain name","C. It is used by TCP to acknowledge bytes","D. It is always routed unchanged across the internet"],"ans":"A","explanation":"Ethernet MAC addresses are used for local-link frame delivery and are replaced at each routed hop."},{"id":"cn-073","q":"When a router forwards an ordinary packet without NAT, which statement is generally true?","opts":["A. The source and destination IP addresses usually remain the same, while the link-layer frame is rebuilt for the next hop","B. The destination MAC address stays the same across every router on the internet","C. TCP ports are always replaced at each hop","D. The DNS name is written into the Ethernet header"],"ans":"A","explanation":"Routers decrement TTL/hop limit and rewrite link-layer headers; IP endpoints normally remain unchanged absent NAT or similar functions."},{"id":"cn-074","q":"Which protocol is commonly used to synchronize clocks across networked systems?","opts":["A. NTP","B. FTP","C. ARP","D. POP3"],"ans":"A","explanation":"Network Time Protocol synchronizes system clocks; its conventional port is UDP 123."},{"id":"cn-075","q":"Which DNS record identifies mail servers for a domain?","opts":["A. A","B. AAAA","C. MX","D. PTR only"],"ans":"C","explanation":"MX records specify mail exchangers for a domain."}]},{"name":"Data Structures & Algorithms","icon":"⌘","description":"150 placement-style theory MCQs on complexity, data structures, sorting, searching, trees, graphs and algorithms.","questions":[{"q":"What is the worst-case time complexity of binary search on a sorted array?","opts":["A. O(1)","B. O(n log n)","C. O(n)","D. O(log n)"],"ans":"D","explanation":"Each comparison halves the remaining search interval.","topic":"Complexity"},{"q":"What is the time complexity of scanning an array once to find its maximum?","opts":["A. O(n)","B. O(log n)","C. O(1)","D. O(n²)"],"ans":"A","explanation":"Every element may need to be inspected.","topic":"Complexity"},{"q":"Two nested loops each run n times. What is their combined time complexity?","opts":["A. O(n)","B. O(log n)","C. O(n²)","D. O(2n)"],"ans":"C","explanation":"The inner body runs n × n times.","topic":"Complexity"},{"q":"What is the time complexity of merge sort in the worst case?","opts":["A. O(n)","B. O(log n)","C. O(n log n)","D. O(n²)"],"ans":"C","explanation":"Merge sort divides the input into logarithmically many levels and processes n items per level.","topic":"Complexity"},{"q":"What is the worst-case time complexity of quicksort?","opts":["A. O(log n)","B. O(n²)","C. O(n)","D. O(n log n)"],"ans":"B","explanation":"Repeatedly choosing an extreme pivot can create partitions of sizes n−1 and 0.","topic":"Complexity"},{"q":"What is the average-case time complexity of quicksort with reasonably balanced pivots?","opts":["A. O(n² log n)","B. O(n²)","C. O(n log n)","D. O(log n)"],"ans":"C","explanation":"Balanced partitioning gives logarithmic recursion depth with linear work per level.","topic":"Complexity"},{"q":"What is the auxiliary space complexity of iterative binary search?","opts":["A. O(log n)","B. O(n)","C. O(1)","D. O(n log n)"],"ans":"C","explanation":"It uses a fixed number of index variables.","topic":"Complexity"},{"q":"What is the typical auxiliary space complexity of recursive binary search?","opts":["A. O(n²)","B. O(1)","C. O(log n)","D. O(log log n)"],"ans":"C","explanation":"The recursion stack has logarithmic depth.","topic":"Complexity"},{"q":"What is the time complexity of accessing array element a[i] by index?","opts":["A. O(n)","B. O(log n)","C. O(n log n)","D. O(1)"],"ans":"D","explanation":"Array elements are stored contiguously, allowing direct address calculation.","topic":"Complexity"},{"q":"What is the time complexity of inserting at the beginning of an array when elements must shift?","opts":["A. O(log n)","B. O(n log n)","C. O(n)","D. O(1)"],"ans":"C","explanation":"Up to n existing elements must be shifted one position.","topic":"Complexity"},{"q":"What is the time complexity of inserting at the head of a singly linked list when the head pointer is known?","opts":["A. O(n²)","B. O(n)","C. O(1)","D. O(log n)"],"ans":"C","explanation":"Only the new node link and head pointer need updating.","topic":"Complexity"},{"q":"Searching for a value in an unsorted linked list takes what worst-case time?","opts":["A. O(log n)","B. O(1)","C. O(n log n)","D. O(n)"],"ans":"D","explanation":"The value may be in the final node or absent.","topic":"Complexity"},{"q":"What is the time complexity of pushing onto a stack implemented with a dynamic array, amortized?","opts":["A. O(log n)","B. O(1)","C. O(n log n)","D. O(n) always"],"ans":"B","explanation":"Most pushes are constant time; occasional resizing is spread over many pushes.","topic":"Complexity"},{"q":"What is the time complexity of inserting into a binary heap and restoring heap order?","opts":["A. O(n)","B. O(n log n)","C. O(log n)","D. O(1)"],"ans":"C","explanation":"The inserted item can move up at most the heap height.","topic":"Complexity"},{"q":"What is the time complexity of retrieving the minimum from a min-heap?","opts":["A. O(n log n)","B. O(log n)","C. O(1)","D. O(n)"],"ans":"C","explanation":"The minimum is stored at the root.","topic":"Complexity"},{"q":"What is the time complexity of deleting the root of a binary heap?","opts":["A. O(1)","B. O(n)","C. O(n²)","D. O(log n)"],"ans":"D","explanation":"Replacing the root and sifting down takes at most the heap height.","topic":"Complexity"},{"q":"What is the worst-case lookup time in a well-balanced binary search tree?","opts":["A. O(1)","B. O(log n)","C. O(log log n)","D. O(n²)"],"ans":"B","explanation":"A balanced tree has logarithmic height.","topic":"Complexity"},{"q":"What is the worst-case lookup time in a completely skewed BST?","opts":["A. O(n log n)","B. O(log n)","C. O(n)","D. O(1)"],"ans":"C","explanation":"A skewed BST can behave like a linked list.","topic":"Complexity"},{"q":"What is the worst-case search time in a hash table with all keys colliding?","opts":["A. O(n)","B. O(n log n)","C. O(1)","D. O(log n)"],"ans":"A","explanation":"All entries may need to be examined within one collision chain or bucket.","topic":"Complexity"},{"q":"What is the time complexity of BFS using an adjacency list?","opts":["A. O(V²) always","B. O(V + E)","C. O(E log V)","D. O(log V)"],"ans":"B","explanation":"Each vertex and each edge is processed a constant number of times.","topic":"Complexity"},{"q":"What is the time complexity of DFS using an adjacency list?","opts":["A. O(E²)","B. O(1)","C. O(V + E)","D. O(V log V)"],"ans":"C","explanation":"DFS visits vertices and scans adjacency lists.","topic":"Complexity"},{"q":"What is the time complexity of Dijkstra’s algorithm with a binary heap and adjacency lists?","opts":["A. O((V + E) log V)","B. O(E²)","C. O(log V)","D. O(V²) in all implementations"],"ans":"A","explanation":"Heap operations for vertices/edges introduce logarithmic factors.","topic":"Complexity"},{"q":"What is the time complexity of checking every pair of elements with two nested loops?","opts":["A. O(n²)","B. O(n log n)","C. O(n)","D. O(log n)"],"ans":"A","explanation":"The number of pairs grows quadratically.","topic":"Complexity"},{"q":"What is the time complexity of a loop that repeatedly doubles i until i ≥ n?","opts":["A. O(1)","B. O(n)","C. O(log n)","D. O(n log n)"],"ans":"C","explanation":"The number of doublings needed to reach n is logarithmic.","topic":"Complexity"},{"q":"What is the time complexity of three nested loops each running n times?","opts":["A. O(3n)","B. O(n³)","C. O(log n)","D. O(n²)"],"ans":"B","explanation":"The body executes n × n × n times.","topic":"Complexity"},{"q":"What is the complexity of f(n) = 3n² + 5n + 8 in Big-O notation?","opts":["A. O(n)","B. O(log n)","C. O(n³)","D. O(n²)"],"ans":"D","explanation":"The highest-order term dominates as n grows.","topic":"Complexity"},{"q":"Which growth rate is asymptotically fastest among these?","opts":["A. O(n)","B. O(n²)","C. O(log n)","D. O(n log n)"],"ans":"C","explanation":"Logarithmic growth increases more slowly than the listed polynomial and linearithmic rates.","topic":"Complexity"},{"q":"If an algorithm performs a fixed number of operations independent of input size, its time complexity is:","opts":["A. O(log n)","B. O(n²)","C. O(n)","D. O(1)"],"ans":"D","explanation":"The running time does not scale with n.","topic":"Complexity"},{"q":"What is the time complexity of building a binary heap using bottom-up heapify?","opts":["A. O(n log n)","B. O(n²)","C. O(n)","D. O(log n)"],"ans":"C","explanation":"Most nodes are near the leaves and require little sifting; total work is linear.","topic":"Complexity"},{"q":"What is the worst-case time complexity of counting sort for n items and key range k?","opts":["A. O(n log n)","B. O(n + k)","C. O(nk)","D. O(log n)"],"ans":"B","explanation":"It counts key frequencies and then processes the input and key range.","topic":"Complexity"},{"q":"Which sorting algorithm repeatedly selects the smallest remaining element and places it next?","opts":["A. Heap sort","B. Selection sort","C. Insertion sort","D. Merge sort"],"ans":"B","explanation":"Selection sort selects an extreme element from the unsorted portion each pass.","topic":"Sorting"},{"q":"Which sorting algorithm is usually efficient for small or nearly sorted arrays?","opts":["A. Insertion sort","B. Counting sort","C. Heap sort","D. Selection sort"],"ans":"A","explanation":"Insertion sort makes few shifts when elements are already close to their final positions.","topic":"Sorting"},{"q":"Which sorting algorithm guarantees O(n log n) worst-case time and is commonly in-place?","opts":["A. Bubble sort","B. Selection sort","C. Quicksort","D. Heap sort"],"ans":"D","explanation":"Heap sort maintains a heap and repeatedly extracts the root.","topic":"Sorting"},{"q":"Which stable comparison sort guarantees O(n log n) worst-case time?","opts":["A. Heap sort","B. Quicksort","C. Selection sort","D. Merge sort"],"ans":"D","explanation":"Merge sort combines sorted halves and preserves equal-item order when implemented stably.","topic":"Sorting"},{"q":"Which sorting algorithm is stable in its standard implementation?","opts":["A. Quicksort in its typical in-place form","B. Heap sort","C. Insertion sort","D. Selection sort"],"ans":"C","explanation":"Insertion sort shifts only larger elements, preserving the relative order of equal keys.","topic":"Sorting"},{"q":"Which algorithm is typically unstable in its standard in-place implementation?","opts":["A. Bubble sort with no swaps on equals","B. Merge sort","C. Insertion sort","D. Heap sort"],"ans":"D","explanation":"Heap operations can reorder equal-key elements.","topic":"Sorting"},{"q":"After one complete left-to-right pass of bubble sort in ascending order, what is guaranteed?","opts":["A. All elements are in reverse order","B. The smallest element is at the end","C. The largest element is at the end","D. The array is fully sorted"],"ans":"C","explanation":"Each adjacent comparison moves larger values rightward.","topic":"Sorting"},{"q":"Which algorithm is based on divide and conquer?","opts":["A. Merge sort","B. Insertion sort","C. Bubble sort","D. Selection sort"],"ans":"A","explanation":"Merge sort recursively divides the array and merges sorted halves.","topic":"Sorting"},{"q":"Which sort can achieve O(n) best-case time on an already sorted array with an early-exit check?","opts":["A. Standard merge sort","B. Selection sort","C. Bubble sort","D. Heap sort"],"ans":"C","explanation":"No swaps in the first pass allow the early-exit version to stop.","topic":"Sorting"},{"q":"Which sort is non-comparison-based and works well when integer keys lie in a limited range?","opts":["A. Merge sort","B. Quicksort","C. Counting sort","D. Heap sort"],"ans":"C","explanation":"Counting sort uses frequency counts instead of comparing each pair of keys.","topic":"Sorting"},{"q":"What condition must hold before binary search is applied to an ordinary array?","opts":["A. The array must contain only positive values","B. The array must have even length","C. The array must be sorted","D. The array must contain unique values"],"ans":"C","explanation":"Binary search relies on sorted order to discard half the search space.","topic":"Searching"},{"q":"In binary search, if the target is greater than the middle value in an ascending array, which half remains?","opts":["A. The left half","B. Both halves always","C. The right half","D. Neither half"],"ans":"C","explanation":"All values at or left of the middle are too small.","topic":"Searching"},{"q":"What is the worst-case number of comparisons for linear search in n items when the target is absent?","opts":["A. log₂ n","B. 1","C. n log n","D. n"],"ans":"D","explanation":"Every item must be checked if the target is not present.","topic":"Searching"},{"q":"Which searching method is suitable for an unsorted linked list without preprocessing?","opts":["A. Interpolation search","B. Binary search by index","C. Jump search requiring random access","D. Linear search"],"ans":"D","explanation":"Linked lists do not support efficient indexed middle access, so sequential scanning is appropriate.","topic":"Searching"},{"q":"Interpolation search is most likely to perform well when sorted numeric values are:","opts":["A. Approximately uniformly distributed","B. Stored in a linked list with no indexing","C. Strictly in descending order only","D. All identical"],"ans":"A","explanation":"Its position estimate benefits from a near-uniform value distribution.","topic":"Searching"},{"q":"What does a stable sorting algorithm preserve?","opts":["A. The original array length only","B. Constant auxiliary space in every case","C. The order of unequal elements by input position","D. Relative order of equal-key elements"],"ans":"D","explanation":"Stability preserves the input order among items with equal sort keys.","topic":"Sorting"},{"q":"Which algorithm is usually preferred when memory usage must be O(1) auxiliary and worst-case O(n log n)?","opts":["A. Recursive merge sort with a temporary array","B. Counting sort","C. Heap sort","D. Merge sort on arrays"],"ans":"C","explanation":"Heap sort is in-place with logarithmic-time heap operations.","topic":"Sorting"},{"q":"For a nearly sorted array, why can insertion sort outperform O(n log n) sorts in practice?","opts":["A. It performs few shifts and comparisons","B. It has O(1) worst-case time","C. It skips every already sorted item without checking","D. It always uses hashing"],"ans":"A","explanation":"Its work can approach linear when each item is close to its proper position.","topic":"Sorting"},{"q":"What is the average time complexity of randomized quicksort?","opts":["A. O(n)","B. O(n log n)","C. O(n²)","D. O(log n)"],"ans":"B","explanation":"Random pivots yield expected balanced partitions.","topic":"Sorting"},{"q":"Which sorting algorithm repeatedly merges sorted runs?","opts":["A. Bubble sort","B. Selection sort","C. Insertion sort","D. Merge sort"],"ans":"D","explanation":"Merging combines ordered subarrays into a larger ordered array.","topic":"Sorting"},{"q":"Which algorithm is commonly used to find the k-th smallest item without fully sorting the array?","opts":["A. Prim’s algorithm","B. BFS","C. Binary search on unsorted values","D. Quickselect"],"ans":"D","explanation":"Quickselect partitions around a pivot and recurses only into the relevant side.","topic":"Searching"},{"q":"When all values are equal, how can a two-way quicksort partition strategy perform poorly?","opts":["A. It may create highly unbalanced partitions","B. It automatically becomes counting sort","C. It becomes guaranteed O(n)","D. It needs no comparisons"],"ans":"A","explanation":"Some two-way partition schemes fail to split equal keys effectively.","topic":"Sorting"},{"q":"Which property is essential for applying counting sort directly to values?","opts":["A. The input must already be sorted","B. Keys can be mapped to a manageable range of counts","C. All keys must be distinct","D. Input must be a linked list"],"ans":"B","explanation":"The count array must be feasible for the key domain.","topic":"Sorting"},{"q":"What is the main purpose of a partition step in quicksort?","opts":["A. Place pivot-relative values on either side of a pivot","B. Build a queue","C. Compute shortest paths","D. Merge two sorted halves"],"ans":"A","explanation":"Partitioning establishes the pivot boundary used by recursive calls.","topic":"Sorting"},{"q":"Which technique can find an element in a rotated sorted array in O(log n) time?","opts":["A. Linear scan only","B. Bubble sort","C. Depth-first search","D. Modified binary search"],"ans":"D","explanation":"A modified binary search identifies which half remains sorted.","topic":"Searching"},{"q":"Which data structure stores elements in contiguous memory in the usual array model?","opts":["A. Array","B. Binary tree","C. Singly linked list","D. Graph adjacency list of linked nodes"],"ans":"A","explanation":"Arrays provide contiguous indexed storage.","topic":"Linear structures"},{"q":"What is the main advantage of a linked list over a fixed-size array?","opts":["A. Binary search is always O(log n)","B. It can grow node by node without requiring a contiguous block","C. Always uses less memory","D. O(1) random access"],"ans":"B","explanation":"Linked nodes can be allocated individually as needed.","topic":"Linear structures"},{"q":"What extra information does a doubly linked-list node store compared with a singly linked-list node?","opts":["A. A pointer to the previous node","B. A second data value","C. A tree height","D. A hash code only"],"ans":"A","explanation":"A doubly linked list links each node in both directions.","topic":"Linear structures"},{"q":"When a pointer to a node is already known, insertion immediately after it in a singly linked list takes:","opts":["A. O(1) time","B. O(n log n) time","C. O(log n) time","D. O(n) time"],"ans":"A","explanation":"Only a constant number of links must be updated.","topic":"Linear structures"},{"q":"Deleting the last node of a singly linked list generally takes O(n) when:","opts":["A. A tail pointer and previous pointer are available","B. The list is empty","C. Only the head pointer is available","D. The list has exactly one node"],"ans":"C","explanation":"The predecessor of the last node must be found by traversal.","topic":"Linear structures"},{"q":"Which data structure follows LIFO order?","opts":["A. Queue","B. FIFO buffer","C. Priority queue","D. Stack"],"ans":"D","explanation":"The most recently inserted item is removed first.","topic":"Stacks and queues"},{"q":"Which data structure follows FIFO order?","opts":["A. Binary search tree","B. Call stack","C. Queue","D. Stack"],"ans":"C","explanation":"The earliest inserted item is removed first.","topic":"Stacks and queues"},{"q":"Which stack operation removes the top item?","opts":["A. Enqueue","B. Peek","C. Push","D. Pop"],"ans":"D","explanation":"Pop removes the most recently added stack element.","topic":"Stacks and queues"},{"q":"Which stack operation reads the top item without removing it?","opts":["A. Pop","B. Peek (top)","C. Dequeue","D. Push"],"ans":"B","explanation":"Peek returns the top element while leaving the stack unchanged.","topic":"Stacks and queues"},{"q":"What condition causes stack underflow?","opts":["A. Pushing into a full bounded stack","B. Adding to a queue","C. A hash collision","D. Attempting to pop from an empty stack"],"ans":"D","explanation":"Underflow occurs when a removal is attempted with no element available.","topic":"Stacks and queues"},{"q":"Which structure is commonly used to check balanced parentheses?","opts":["A. Queue","B. Heap","C. Stack","D. Disjoint-set union"],"ans":"C","explanation":"Opening delimiters are pushed and matched when closing delimiters appear.","topic":"Stacks and queues"},{"q":"Which data structure is commonly used to evaluate postfix expressions?","opts":["A. Queue","B. Stack","C. Graph","D. Trie"],"ans":"B","explanation":"Operands are pushed and operators pop their operands.","topic":"Stacks and queues"},{"q":"Which data structure is most suitable for implementing undo in a text editor?","opts":["A. Adjacency matrix","B. Min-heap","C. Stack","D. Queue"],"ans":"C","explanation":"The most recent action is typically undone first.","topic":"Stacks and queues"},{"q":"In a circular queue, what is the main benefit of wrapping indices around?","opts":["A. Making every operation O(n)","B. Reusing freed slots at the beginning of the array","C. Eliminating front and rear indices","D. Keeping the queue permanently sorted"],"ans":"B","explanation":"Circular indexing avoids wasting space after dequeues.","topic":"Stacks and queues"},{"q":"In a queue implemented using a linked list with front and rear pointers, enqueue at the rear is typically:","opts":["A. O(n²)","B. O(n)","C. O(log n)","D. O(1)"],"ans":"D","explanation":"The rear pointer permits insertion without traversing the list.","topic":"Stacks and queues"},{"q":"A deque supports which operations?","opts":["A. Only priority-based removal","B. Insertion and deletion at both ends","C. Only random indexed access","D. Insertion only at front and deletion only at rear"],"ans":"B","explanation":"A double-ended queue permits operations at the front and rear.","topic":"Stacks and queues"},{"q":"Which data structure is generally used for level-order traversal of a tree?","opts":["A. Queue","B. Hash table","C. Min-heap","D. Stack only"],"ans":"A","explanation":"Level-order traversal processes nodes in breadth-first order.","topic":"Trees"},{"q":"Which data structure is used by a typical iterative depth-first traversal?","opts":["A. Queue only","B. Priority queue","C. Circular array only","D. Stack"],"ans":"D","explanation":"DFS stores pending nodes on a stack, explicitly or via recursion.","topic":"Graphs"},{"q":"What is the time complexity of inserting at index 0 in an array of n items?","opts":["A. O(n)","B. O(log n)","C. O(n log n)","D. O(1) always"],"ans":"A","explanation":"Existing elements need to shift to make room.","topic":"Linear structures"},{"q":"What is the time complexity of accessing the k-th node in a singly linked list from the head?","opts":["A. O(log k)","B. O(k log k)","C. O(1)","D. O(k)"],"ans":"D","explanation":"The list must be traversed node by node.","topic":"Linear structures"},{"q":"What is a common drawback of linked lists compared with arrays?","opts":["A. They cannot insert at the head efficiently","B. They cannot grow dynamically","C. They require sorted data","D. Extra memory for pointers and poor cache locality"],"ans":"D","explanation":"Pointers consume memory and nodes may be scattered in memory.","topic":"Linear structures"},{"q":"What does a priority queue remove first?","opts":["A. Always the oldest item","B. The item at the middle index","C. Always the newest item","D. The item with the highest priority according to its ordering rule"],"ans":"D","explanation":"Removal is determined by priority, not simply insertion order.","topic":"Stacks and queues"},{"q":"Which implementation is commonly used for an efficient priority queue?","opts":["A. Binary heap","B. Unsorted string only","C. Stack","D. Doubly linked list with no ordering"],"ans":"A","explanation":"A binary heap supports efficient insertion and access to the priority extremum.","topic":"Heaps"},{"q":"In a stack implemented by an array, what is the role of top?","opts":["A. It points to the next graph vertex","B. It stores the bottom element permanently","C. It identifies the current top element or its index","D. It counts queue rotations only"],"ans":"C","explanation":"The top marker tracks where push and pop operate.","topic":"Stacks and queues"},{"q":"What is the typical time complexity of enqueue and dequeue in a correctly implemented circular array queue?","opts":["A. O(log n)","B. O(n log n)","C. O(n) each","D. O(1)"],"ans":"D","explanation":"Each operation updates a fixed number of indices.","topic":"Stacks and queues"},{"q":"Which structure is most suitable for repeatedly retrieving the largest item while accepting new items?","opts":["A. Unsorted singly linked list with no scan","B. Stack","C. Max-heap","D. Binary search by array index"],"ans":"C","explanation":"A max-heap keeps the largest value at its root.","topic":"Heaps"},{"q":"What is the key difference between a stack and a queue?","opts":["A. Stack requires a tree","B. Stack is always sorted; queue is not","C. Queue permits no insertion","D. Stack removes the newest item; queue removes the oldest item"],"ans":"D","explanation":"Their removal orders are LIFO and FIFO respectively.","topic":"Stacks and queues"},{"q":"Which data structure is appropriate for browser back-navigation history?","opts":["A. Stack","B. Trie","C. Queue","D. Min-heap"],"ans":"A","explanation":"The most recently visited page is the first one returned to.","topic":"Stacks and queues"},{"q":"Which operation on a singly linked list requires no traversal when the head pointer is known?","opts":["A. Find the middle node","B. Insert a new node at the head","C. Search for a given value","D. Delete the tail in a multi-node list"],"ans":"B","explanation":"Head insertion updates only the new node and head pointer.","topic":"Linear structures"},{"q":"What does a sentinel (dummy) node often simplify in a linked list?","opts":["A. Heap balancing","B. Hash function computation","C. Boundary-case handling for insertions and deletions","D. Binary search"],"ans":"C","explanation":"A dummy node can reduce special cases around the head.","topic":"Linear structures"},{"q":"In a binary tree, what is the maximum number of children a node can have?","opts":["A. Unlimited","B. 2","C. 3","D. 1"],"ans":"B","explanation":"A binary-tree node has at most a left and a right child.","topic":"Trees"},{"q":"In a binary search tree, keys in the left subtree are conventionally:","opts":["A. Always equal to the node key","B. Less than the node key","C. Greater than the node key","D. Unrelated to the node key"],"ans":"B","explanation":"The BST ordering property places smaller keys to the left.","topic":"Trees"},{"q":"Which traversal of a BST visits keys in nondecreasing order, assuming the standard duplicate policy?","opts":["A. Level order","B. Inorder","C. Postorder","D. Preorder"],"ans":"B","explanation":"Inorder visits left subtree, node, then right subtree.","topic":"Trees"},{"q":"Which traversal visits a node before its children?","opts":["A. Inorder","B. Preorder","C. Reverse level order","D. Postorder"],"ans":"B","explanation":"Preorder order is root, left, right.","topic":"Trees"},{"q":"Which traversal visits a node after its children?","opts":["A. Preorder","B. Level order","C. Postorder","D. Inorder"],"ans":"C","explanation":"Postorder processes child subtrees before the node.","topic":"Trees"},{"q":"What is the height of a perfectly balanced binary tree with n nodes asymptotically?","opts":["A. O(log n)","B. O(n²)","C. O(1) for all n","D. O(n)"],"ans":"A","explanation":"The number of nodes roughly doubles at each level.","topic":"Trees"},{"q":"Which self-balancing BST uses balance factors and rotations?","opts":["A. AVL tree","B. Binary heap","C. Trie","D. Disjoint-set forest"],"ans":"A","explanation":"AVL trees maintain a bounded height using rotations.","topic":"Trees"},{"q":"What is the balance-factor condition for each node in an AVL tree?","opts":["A. The root must always be the smallest key","B. The heights of its subtrees differ by at most 1","C. Every node must have two children","D. Both subtrees must have equal node counts"],"ans":"B","explanation":"AVL balance factors are restricted to −1, 0, or +1.","topic":"Trees"},{"q":"Which rotation corrects an AVL left-left imbalance?","opts":["A. Right rotation","B. Left-right rotation only","C. Left rotation","D. No rotation"],"ans":"A","explanation":"A right rotation restores balance after a left-left insertion pattern.","topic":"Trees"},{"q":"In a min-heap, which property must hold for each parent and child?","opts":["A. Parent key is no greater than child keys","B. Parent key is always greater than child keys","C. Inorder traversal is sorted","D. Every level is fully sorted left to right"],"ans":"A","explanation":"The heap-order property places a minimum at the root.","topic":"Heaps"},{"q":"Which structure is particularly suitable for prefix searches over words?","opts":["A. Stack","B. Binary heap","C. Disjoint-set union","D. Trie"],"ans":"D","explanation":"A trie shares paths for common prefixes.","topic":"Hashing and tries"},{"q":"What is a hash collision?","opts":["A. Two different keys map to the same table index","B. A key is stored in two trees","C. The table becomes sorted","D. A pointer becomes null"],"ans":"A","explanation":"Different keys can produce the same hash-table slot.","topic":"Hashing"},{"q":"Which is a common collision-resolution method?","opts":["A. Merge sort","B. Binary search only","C. Tree traversal only","D. Separate chaining"],"ans":"D","explanation":"Each table bucket stores a collection of entries that hash to it.","topic":"Hashing"},{"q":"In open addressing, where are colliding keys stored?","opts":["A. In a separate linked list for every bucket necessarily","B. Always in a second hash table","C. In other available slots within the table","D. Only outside memory"],"ans":"C","explanation":"Probing searches for an alternate free slot in the table.","topic":"Hashing"},{"q":"What does a load factor of a hash table measure?","opts":["A. Number of collisions divided by key length","B. Number of buckets squared","C. Number of stored entries divided by number of slots","D. Table capacity divided by number of hash functions"],"ans":"C","explanation":"Load factor expresses how full the table is.","topic":"Hashing"},{"q":"Why can resizing a hash table improve performance?","opts":["A. It guarantees every lookup is O(1) worst case","B. It sorts all keys automatically","C. It reduces load factor and often reduces collisions","D. It eliminates the need for a hash function"],"ans":"C","explanation":"A larger table can spread entries across more buckets.","topic":"Hashing"},{"q":"Which traversal is commonly used to delete an entire binary tree safely?","opts":["A. Level order only","B. Inorder only","C. Preorder only","D. Postorder"],"ans":"D","explanation":"Children should be processed before deleting their parent.","topic":"Trees"},{"q":"A full binary tree is one in which every node has:","opts":["A. Either 0 or 2 children","B. Exactly 1 child","C. Exactly 2 children including leaves","D. At most 3 children"],"ans":"A","explanation":"Full means nodes have either two children or none.","topic":"Trees"},{"q":"In a complete binary tree, levels are filled:","opts":["A. Only on the right side first","B. In arbitrary positions","C. With exactly one node per level","D. From top to bottom, left to right, with only the last level possibly incomplete"],"ans":"D","explanation":"Completeness fills each level before starting the next and left-aligns the last.","topic":"Trees"},{"q":"Which data structure is usually used to implement a heap efficiently?","opts":["A. Doubly linked list only","B. Adjacency list","C. Hash set","D. Array"],"ans":"D","explanation":"Parent and child indices map naturally into array positions.","topic":"Heaps"},{"q":"What is the purpose of a hash function?","opts":["A. Sort the table in ascending order","B. Guarantee no collisions","C. Encrypt the key reversibly","D. Map a key to a hash value used to select a table location"],"ans":"D","explanation":"The hash value helps determine where an entry is placed or searched.","topic":"Hashing"},{"q":"Which traversal of a general tree visits nodes level by level?","opts":["A. Reverse postorder only","B. Breadth-first (level-order) traversal","C. Inorder only","D. Postorder only"],"ans":"B","explanation":"A queue processes nodes in successive levels.","topic":"Trees"},{"q":"What is the worst-case search time in an unbalanced BST?","opts":["A. O(log log n)","B. O(log n) always","C. O(1)","D. O(n)"],"ans":"D","explanation":"Its height can be n−1 when it degenerates into a chain.","topic":"Trees"},{"q":"Which data structure is commonly used to efficiently find the minimum repeatedly?","opts":["A. Min-heap","B. Queue","C. Unsorted array without scanning","D. Stack"],"ans":"A","explanation":"The minimum remains at the root after heap operations.","topic":"Heaps"},{"q":"What does path compression optimize in a disjoint-set (union-find) structure?","opts":["A. Balancing an AVL tree","B. Find operations by making nodes point closer to the representative","C. Searching a string prefix","D. Sorting all sets"],"ans":"B","explanation":"Path compression flattens parent paths during find operations.","topic":"Disjoint sets"},{"q":"Which algorithm finds shortest paths from a source in an unweighted graph?","opts":["A. DFS","B. Prim’s algorithm","C. Kruskal’s algorithm","D. BFS"],"ans":"D","explanation":"BFS explores vertices in increasing number of edges from the source.","topic":"Graphs"},{"q":"Which algorithm finds a minimum spanning tree by repeatedly taking a lightest crossing edge from a growing tree?","opts":["A. Bellman–Ford","B. Prim’s algorithm","C. Dijkstra’s algorithm","D. Floyd–Warshall"],"ans":"B","explanation":"Prim grows one connected tree by selecting a minimum-weight edge crossing its cut.","topic":"Graphs"},{"q":"Which algorithm sorts edges by weight and adds an edge if it does not create a cycle, for an MST?","opts":["A. BFS","B. Kruskal’s algorithm","C. Topological sort","D. Dijkstra’s algorithm"],"ans":"B","explanation":"Kruskal uses edge ordering and cycle detection, commonly with union-find.","topic":"Graphs"},{"q":"Which algorithm can handle negative edge weights in single-source shortest paths, provided no reachable negative cycle exists?","opts":["A. Binary search","B. Dijkstra’s algorithm in its standard form","C. Prim’s algorithm","D. Bellman–Ford"],"ans":"D","explanation":"Bellman–Ford relaxes edges repeatedly and detects reachable negative cycles.","topic":"Graphs"},{"q":"Which algorithm computes shortest paths between all pairs of vertices using dynamic programming?","opts":["A. Topological sort","B. Floyd–Warshall","C. BFS only","D. Kruskal"],"ans":"B","explanation":"Floyd–Warshall updates distances using each vertex as an intermediate.","topic":"Graphs"},{"q":"A topological ordering exists only for which kind of directed graph?","opts":["A. Any undirected graph","B. Directed acyclic graph (DAG)","C. Every directed graph","D. A graph containing a directed cycle"],"ans":"B","explanation":"A directed cycle makes a valid topological ordering impossible.","topic":"Graphs"},{"q":"Which data structure is commonly used in Kahn’s topological-sort algorithm?","opts":["A. Stack of sorted keys only","B. Min-heap of all edges necessarily","C. Queue of zero-indegree vertices","D. Hash function only"],"ans":"C","explanation":"Kahn’s algorithm repeatedly removes zero-indegree vertices from a queue.","topic":"Graphs"},{"q":"What is a cycle in a graph?","opts":["A. Any path with one edge","B. A path that returns to its starting vertex without repeating edges, under the chosen cycle definition","C. A vertex with degree zero","D. A graph with no vertices"],"ans":"B","explanation":"A cycle begins and ends at the same vertex.","topic":"Graphs"},{"q":"Which graph representation uses O(V²) space regardless of the number of edges?","opts":["A. Adjacency matrix","B. Edge list","C. Adjacency list","D. Edge list representation"],"ans":"A","explanation":"An adjacency matrix stores a value for every possible vertex pair.","topic":"Graphs"},{"q":"For a sparse graph, which representation usually uses less space?","opts":["A. A complete list of all vertex pairs","B. Adjacency list","C. A V-by-V distance matrix","D. Adjacency matrix"],"ans":"B","explanation":"An adjacency list stores existing edges rather than all possible pairs.","topic":"Graphs"},{"q":"Which algorithmic paradigm solves a problem by combining solutions to overlapping subproblems and storing their results?","opts":["A. Greedy method only","B. Randomized partitioning","C. Brute force only","D. Dynamic programming"],"ans":"D","explanation":"Dynamic programming avoids recomputing overlapping subproblems.","topic":"Algorithms"},{"q":"Which paradigm makes a locally optimal choice at each step, hoping to reach a global optimum?","opts":["A. Greedy algorithm","B. Backtracking only","C. Dynamic programming in all cases","D. Linear search"],"ans":"A","explanation":"Greedy algorithms commit to a local choice at each stage.","topic":"Algorithms"},{"q":"Which technique explores candidate solutions and abandons a partial solution when it cannot lead to a valid answer?","opts":["A. Merge sort","B. Hashing","C. Backtracking","D. Binary search"],"ans":"C","explanation":"Backtracking prunes invalid or unpromising partial candidates.","topic":"Algorithms"},{"q":"Which problem is a classic application of dynamic programming?","opts":["A. Printing a fixed string","B. Checking whether a number is even","C. 0/1 knapsack","D. Finding an array maximum with one scan only"],"ans":"C","explanation":"Dynamic programming considers subproblems over items and capacities.","topic":"Algorithms"},{"q":"Which algorithmic technique is used by merge sort?","opts":["A. Greedy selection","B. Divide and conquer","C. Hash-based lookup","D. Backtracking over subsets"],"ans":"B","explanation":"It divides the array, sorts each half, and combines them.","topic":"Algorithms"},{"q":"What is the main purpose of memoization?","opts":["A. Force every call to recompute its result","B. Sort a hash table","C. Reduce array size by deleting duplicates","D. Cache results of function calls for repeated subproblems"],"ans":"D","explanation":"Memoization stores computed results to avoid repeated work.","topic":"Algorithms"},{"q":"Which algorithm finds a minimum spanning tree, not shortest paths from a source?","opts":["A. Kruskal’s algorithm","B. Bellman–Ford","C. Dijkstra’s algorithm","D. Floyd–Warshall"],"ans":"A","explanation":"Kruskal minimizes total spanning-tree edge weight.","topic":"Graphs"},{"q":"What does a minimum spanning tree connect?","opts":["A. All directed cycles","B. Every pair of vertices with a direct edge","C. All vertices of a connected, weighted, undirected graph with minimum total edge weight","D. Only the source to every vertex by shortest paths"],"ans":"C","explanation":"An MST spans all vertices while minimizing total edge weight without cycles.","topic":"Graphs"},{"q":"Which algorithm is suitable for detecting connected components in an undirected graph?","opts":["A. Merge sort","B. DFS or BFS","C. Binary search","D. Counting sort"],"ans":"B","explanation":"Graph traversal visits all vertices in each connected component.","topic":"Graphs"},{"q":"What is the space complexity of an adjacency matrix for V vertices?","opts":["A. O(log V)","B. O(V + E) always","C. O(V²)","D. O(E log V)"],"ans":"C","explanation":"The matrix has V rows and V columns.","topic":"Graphs"},{"q":"Which technique can detect a cycle in a directed graph using DFS?","opts":["A. Track vertices currently in the recursion stack","B. Use binary search on the adjacency matrix","C. Count only isolated vertices","D. Sort all vertices by numeric label"],"ans":"A","explanation":"A back edge to a currently active DFS vertex indicates a directed cycle.","topic":"Graphs"},{"q":"What is the key requirement for Dijkstra’s algorithm in its standard form?","opts":["A. Edge weights must be nonnegative","B. The graph must be a tree","C. Every edge must have weight 1","D. The graph must be undirected"],"ans":"A","explanation":"Negative weights can invalidate Dijkstra’s greedy finalization step.","topic":"Graphs"},{"q":"Which approach is most suitable for shortest paths in an unweighted graph?","opts":["A. Breadth-first search","B. Union-find alone","C. Heap sort","D. Kruskal’s algorithm"],"ans":"A","explanation":"Each BFS level represents one additional edge from the source.","topic":"Graphs"},{"q":"What does amortized analysis measure?","opts":["A. Average cost per operation over a sequence, with a worst-case sequence guarantee","B. Memory used by one instruction","C. Expected cost under random input only","D. Only the best-case running time"],"ans":"A","explanation":"Amortized analysis bounds total sequence cost divided across operations.","topic":"Complexity"},{"q":"Which statement about Big-O notation is correct?","opts":["A. It always gives exact runtime in seconds","B. It applies only to recursive algorithms","C. It describes only memory usage","D. It describes an asymptotic upper bound on growth"],"ans":"D","explanation":"Big-O bounds how a function grows for sufficiently large inputs.","topic":"Complexity"},{"q":"Which algorithm finds the greatest common divisor efficiently using repeated remainders?","opts":["A. Rabin–Karp algorithm","B. Euclidean algorithm","C. Kruskal’s algorithm","D. Prim’s algorithm"],"ans":"B","explanation":"The Euclidean algorithm replaces (a,b) with (b, a mod b) until the remainder is zero.","topic":"Algorithms"},{"q":"Which string-search algorithm uses a rolling hash?","opts":["A. Dijkstra","B. Boyer–Moore only","C. Rabin–Karp","D. KMP"],"ans":"C","explanation":"Rabin–Karp compares hash values of text windows and verifies matching candidates.","topic":"Algorithms"},{"q":"Which string-search algorithm uses a prefix-function or failure table to avoid rechecking matched characters?","opts":["A. Heap sort","B. Prim","C. Knuth–Morris–Pratt (KMP)","D. Kruskal"],"ans":"C","explanation":"KMP uses prefix information to shift the pattern efficiently after a mismatch.","topic":"Algorithms"},{"q":"Which data structure is fundamental to a disjoint-set union implementation?","opts":["A. Trie of characters","B. Circular queue only","C. Sorted array only","D. A forest of parent pointers"],"ans":"D","explanation":"Each set is represented as a rooted tree with parent pointers.","topic":"Disjoint sets"},{"q":"What is the purpose of union by rank/size in disjoint sets?","opts":["A. Keep all sets in alphabetical order","B. Keep representative trees shallow","C. Avoid storing parent pointers","D. Make every find operation require a full traversal"],"ans":"B","explanation":"Attaching the smaller or lower-rank tree under the larger helps limit height.","topic":"Disjoint sets"},{"q":"Which structure is best suited for fast membership tests with no ordering requirement?","opts":["A. Hash set","B. Binary heap","C. Queue","D. Stack"],"ans":"A","explanation":"A hash set is designed for membership and uniqueness rather than order.","topic":"Hashing"},{"q":"What does a collision-resistant hash function for a hash table aim to do?","opts":["A. Make every hash value unique for all possible keys","B. Distribute keys broadly across table slots","C. Encrypt data so it cannot be read","D. Guarantee keys are sorted"],"ans":"B","explanation":"A good table hash spreads likely keys to reduce clustering and collisions.","topic":"Hashing"},{"q":"Which algorithm can produce a stable linear-time sort when digit count and base are bounded?","opts":["A. Heap sort","B. Radix sort","C. Selection sort","D. Quicksort"],"ans":"B","explanation":"Radix sort processes digit positions using a stable intermediate sort.","topic":"Sorting"},{"q":"Which structure is useful for maintaining the median of a stream using two heaps?","opts":["A. An adjacency matrix","B. A max-heap for the lower half and a min-heap for the upper half","C. Two stacks sorted by insertion time","D. One FIFO queue only"],"ans":"B","explanation":"The two heaps keep the middle values at their roots.","topic":"Heaps"},{"q":"In a graph, what does a vertex’s degree represent in an undirected graph?","opts":["A. The shortest path to the source","B. The weight of its smallest edge","C. The number of incident edges","D. The total number of vertices"],"ans":"C","explanation":"Degree counts edges incident to the vertex, with a loop conventionally counting twice.","topic":"Graphs"},{"q":"Which algorithm is commonly used to find strongly connected components in a directed graph?","opts":["A. Prim’s algorithm","B. Kosaraju’s algorithm","C. Insertion sort","D. Binary search"],"ans":"B","explanation":"Kosaraju uses DFS passes on the graph and its transpose.","topic":"Graphs"},{"q":"What is the main benefit of a sentinel value in a search loop?","opts":["A. It sorts the input automatically","B. It removes the need to compare values","C. It can simplify loop termination or boundary checks","D. It guarantees logarithmic time"],"ans":"C","explanation":"A sentinel can provide a known stopping condition and reduce special-case checks.","topic":"Algorithms"},{"q":"Which approach is appropriate for finding a pair in a sorted array that sums to target in O(n) time?","opts":["A. Nested loops over every pair","B. Two pointers moving inward","C. BFS","D. Heapify the array repeatedly"],"ans":"B","explanation":"Sorted order lets pointer movement eliminate impossible pairs.","topic":"Algorithms"},{"q":"Which method is commonly used to find the shortest path in a DAG even with negative edge weights?","opts":["A. Prim’s algorithm","B. Binary search","C. Topological order with edge relaxation","D. Dijkstra without restrictions"],"ans":"C","explanation":"Processing vertices topologically allows each edge to be relaxed once.","topic":"Graphs"},{"q":"What does the recurrence T(n) = 2T(n/2) + O(n) describe asymptotically?","opts":["A. O(n)","B. O(n²)","C. O(log n)","D. O(n log n)"],"ans":"D","explanation":"There are log n levels with O(n) total work per level.","topic":"Complexity"}]}];
